type TreeError = {
    readonly code: "node-not-found";
    readonly nodeId: NodeId;
} | {
    readonly code: "duplicate-node-id";
    readonly nodeId: NodeId;
}
/** An id this delta removed, re-inserted as a different node. */
 | {
    readonly code: "recycled-node-id";
    readonly nodeId: NodeId;
} | {
    readonly code: "not-a-container";
    readonly nodeId: NodeId;
    readonly nodeKind: NodeKind;
} | {
    readonly code: "index-out-of-range";
    readonly parentId: NodeId;
    readonly index: number;
    readonly childCount: number;
} | {
    readonly code: "move-into-self";
    readonly nodeId: NodeId;
} | {
    readonly code: "move-into-descendant";
    readonly nodeId: NodeId;
    readonly parentId: NodeId;
} | {
    readonly code: "root-not-detachable";
