     */
    readonly frameAdaptive: "loom-frame-adaptive";
    /** A card whose title anchor is stretched over the whole surface. */
    readonly cover: "loom-cover";
    /** That anchor. Its `::after` is what makes the surface clickable. */
    readonly coverLink: "loom-cover-link";
    /** A card's cover image, cropped to a ratio the card owns rather than the file does. */
    readonly coverMedia: "loom-cover-media";
    /** A card's padded interior, so a lead layout can set it beside the cover. */
    readonly coverBody: "loom-cover-body";
    /** A `loom.article-grid` running its first piece across the top. */
    readonly lead: "loom-lead";
    /** One `loom.field`. Named so the form it sits in can size it in a row. */
    readonly field: "loom-field";
    /** Any control inside a field: the focus ring, the hover, the placeholder. */
    readonly input: "loom-input";
    /** The wrapper that draws a select's chevron, since the native one is not the palette's. */
