const WIDTHS: {
    readonly full: "100%";
    readonly wide: "1120px";
    readonly readable: "68ch";
}

type Composition = {
    /**
     * Lower-case words joined by hyphens, the way an anchor or a slot name is.
     */
    readonly id: string;
    /** Which band of a page this is a design of. */
    readonly part: CompositionPart;
    /** What a person choosing it from a list reads. */
    readonly label: string;
    /**
     * What lands on the page, in one clause, said before it happens.
     */
    readonly promise: string;
    /** The interpreter's own words about why this subtree answers that ask. */
    readonly rationale: string;
    /** Every primitive type the subtree uses, for the catalogue and the audit. */
    readonly uses: readonly string[];
    readonly build: (ids: IdFactory) => ElementNode;
};

type Band = Omit<Composition, "part"> & {
    readonly part: string;
};

type CompositionTarget = {
    readonly parentId?: NodeId;
    /** Clamped to the parent's current child count, never trusted as an index. */
    readonly index?: number;
};

type CompositionPlan = {
    readonly outcome: "planned";
    readonly operations: readonly TreeOperation[];
}
/**
 * The named parent is not in this tree, so there is nowhere to put the band.
 */
 | {
    readonly outcome: "no-such-parent";
    readonly parentId: NodeId;
};

type DocumentComposition = Omit<Composition, "part"> & {
    readonly part: DocumentPart;
};

type CataloguedProp = {
    readonly name: string;
    readonly required: boolean;
};

type CataloguedPrimitive = {
    readonly type: PrimitiveType;
    /** One line, written by the primitive's author, about what it is for. */
    readonly description: string;
    /**
     * Declared props, name-sorted. `undefined` when the declared schema is not an
     * object schema and its keys therefore cannot be enumerated — unknown, which
     * is not the same claim as "none".
     */
    readonly props: readonly CataloguedProp[] | undefined;
    readonly slots: readonly SlotName[];
    /**
     * The binding names this primitive reads an answer under, in declaration
     * order. `undefined` when its author has not said — which, like `props`, is
     * not the same claim as "none" and is not rounded to one.
     */
    readonly reads: readonly BindingDeclaration<BindingName>[] | undefined;
};

type ClosedChoice = {
    readonly name: string;
    readonly options: readonly (string | boolean)[];
};

type PrimitiveAudit = {
    readonly type: PrimitiveType;
    readonly verdict: ConformanceVerdict;
    readonly placement: PlacementVerdict;
    readonly submission: SubmissionVerdict;
    /** What the author declared, beside what the probe saw. */
    readonly declaresSubmits: boolean;
    /** The props this primitive declared it frames. Empty for almost all. */
    readonly framesProps: readonly string[];
    /**
     * The configurations this primitive was probed under that its own schema
     * refuses.
     */
    readonly refusedConfigurations: readonly RefusedConfiguration[];
};

type UnplacedSlots = {
    readonly type: PrimitiveType;
    readonly slots: readonly string[];
};

type UnplacedBehaviours = {
    readonly type: PrimitiveType;
    readonly behaviours: readonly BehaviourName[];
};

type UnansweredReason =
/** The audit was handed no answers for this type at all. */
"no-answers"
/**
 * It was handed some, and no state carried a name this primitive resolves to.
 */
 | "names-not-answered";

type UnansweredReader = {
    readonly type: PrimitiveType;
    /**
     * What its registrant declared it reads, unchanged — either of the two forms
     * a declaration may take.
     */
    readonly reads: readonly BindingDeclaration<BindingName>[];
    readonly reason: UnansweredReason;
};

type RefusedConfiguration = {
    readonly props: JsonObject;
    readonly issues: readonly PropsIssue[];
};

type UnconfiguredReason =
/** The audit was handed no props for this type, and `{}` is not enough. */
"no-props"
/**
 * It was handed some, and the schema refused every configuration they built.
 */
 | "props-not-accepted";

type UnconfiguredPrimitive = {
    readonly type: PrimitiveType;
    /** The props its registration says it must have, name-sorted. */
    readonly required: readonly string[];
    readonly reason: UnconfiguredReason;
    /** Every configuration the schema refused, with what it said about each. */
    readonly refused: readonly RefusedConfiguration[];
};

type ThrowingConfigurations = {
    readonly type: PrimitiveType;
    readonly failures: readonly ProbeFailure[];
    /**
     * Whether *nothing* the probe tried came back — the line between a fault the
     * audit is certain of and one it is only reporting.
     */
    readonly everyConfiguration: boolean;
};

type RegistryAudit = {
    readonly audits: readonly PrimitiveAudit[];
    /** Registered, renders, invisible to the portal. */
    readonly notDecorated: readonly PrimitiveType[];
    /**
     * The probe could not answer — neither a pass nor a failure.
     */
    readonly notProbeable: readonly PrimitiveType[];
    /**
     * Declared a slot and dropped it. Unlike `notDecorated` this loses content
     * rather than a handle, so a host with no portal at all still wants it empty.
     */
    readonly unplacedSlots: readonly UnplacedSlots[];
    /**
     * Declared a behaviour and dropped its control. Like `unplacedSlots` this is
     * a promise the registration made and the component did not keep — and unlike
     * a slot, nothing else on the page hints that something is missing, because
     * the content a behaviour acts on renders perfectly without it.
     */
    readonly unplacedBehaviours: readonly UnplacedBehaviours[];
    /**
     * Declared it reads a binding and was never probed in a state that answered
     * one. Reported rather than failed, like `notDecorated` and for the same
     * reason: whether it matters depends on the deployment. A host
     * auditing the library it ships asserts it empty, because an entry here means
     * every other list on this audit is describing that primitive's unanswered
     * branch and calling it the primitive.
     */
    readonly notAnswered: readonly UnansweredReader[];
    /**
     * Requires props and was probed under none its own schema accepts, so every
     * other list on this audit is describing it under a bag no valid tree carries
     *.
     */
    readonly notConfigured: readonly UnconfiguredPrimitive[];
    /**
     * Renders no children — a leaf. Not a fault: `loom.stat` holds its value and
     * label as props and has nowhere to put a text node. It is here because it is
     * the one fact the renderer cannot derive, and a portal that offers "insert
     * into this node" needs it to avoid offering a place nothing will appear.
     */
    readonly leaves: readonly PrimitiveType[];
    /**
     * Threw on props its own schema **accepts**. A fault whoever registered it
     * wants to know about — a tree the validator accepts can take the page down —
     * and never a reason to distrust the rest of this audit, which is answered by
     * the configurations that did render.
     */
    readonly throwsOnDeclaredProps: readonly ThrowingConfigurations[];
    /**
     * The registered primitives that post, as the probe observed them.
     */
    readonly submits: readonly PrimitiveType[];
    /**
     * Places an address and never declared it posts. Not a broken page — the
     * form works — but the declaration is what a deployment reads to know the
     * seam is load-bearing here, so an undeclared submitter is a form whose need
     * for an endpoint registry is invisible until someone fills it in.
     */
    readonly undeclaredSubmitters: readonly PrimitiveType[];
    /**
     * Declared it posts and placed no address under any configuration probed.
     * This is the failure the submission seam exists to prevent, caught one layer
     * earlier than it would otherwise be: a submit control that goes nowhere
     * renders, looks finished, and reports nothing until a visitor uses it.
     */
    readonly unwiredSubmitters: readonly PrimitiveType[];
    /**
     * The registered primitives that put a prop in a frame.
     */
    readonly frames: readonly PrimitiveType[];
};

type RegistryAuditOptions = {
    /**
     * The answer states each type is probed in, beside the ones its own schema
     * closes over.
     */
    readonly answers?: ReadonlyMap<PrimitiveType, readonly ProbeAnswers[]>;
    /**
     * Props bags each type is probed from, beside the empty one.
     */
    readonly props?: ReadonlyMap<PrimitiveType, readonly JsonObject[]>;
};

type ProbeFailure = {
    readonly props: JsonObject;
    readonly reason: string;
    /**
     * The binding names the node had answers under when it threw, sorted, and
     * absent when it had none.
     */
    readonly answered?: readonly string[];
};

type NotProbeable = {
    readonly outcome: "not-probeable";
    readonly cause: NotProbeableCause;
    readonly reason: string;
    /** Every configuration that threw. Empty exactly when nothing was called. */
    readonly failures: readonly ProbeFailure[];
};

type ConformanceVerdict = {
    readonly outcome: "decorates";
} | {
    readonly outcome: "not-decorated";
} | NotProbeable;

type ProbeConfiguration = {
    readonly props: JsonObject;
    /** `NO_DATA` means *this node asked nothing*, which is most of them. */
    readonly data: NodeData;
};

type ProbeAnswers = {
    /** Answers by binding name, as the render walk would hand them over. */
    readonly data: NodeData;
    /**
     * The props the node carries in this state. Absent means its defaults, which
     * is the configuration a binding name's default was chosen for.
     */
    readonly props?: JsonObject;
};

type PlacementVerdict = {
    readonly outcome: "probed";
    /** Declared slots that no probed configuration placed. */
    readonly unplacedSlots: readonly string[];
    /** Declared behaviours whose control no probed configuration placed. */
    readonly unplacedBehaviours: readonly BehaviourName[];
    /** Whether any probed configuration placed the children it was handed. */
    readonly rendersChildren: boolean;
    /**
     * The configurations that answered — one unasked `{}` alone when the
     * schema closes over nothing and the caller supplied no answers.
     */
    readonly probed: readonly ProbeConfiguration[];
    /**
     * Configurations built from the primitive's own schema that it threw on.
     * Never a reason to distrust the verdict — the configurations that
     * answered still answered.
     */
    readonly threw: readonly ProbeFailure[];
} | NotProbeable;

type SubmissionVerdict = {
    readonly outcome: "places";
} | {
    readonly outcome: "not-placed";
} | NotProbeable;

type ColourPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
};

type ColourVerdict = {
    readonly outcome: "probed";
    /** Ink and ground both set by this primitive. */
    readonly painted: readonly ColourPairing[];
    /** Ink set here, ground left to whatever this is placed in. */
    readonly floating: readonly PaletteSlot[];
    /** Grounds this primitive puts its declared children and slots on. */
    readonly childGrounds: readonly PaletteSlot[];
} | NotProbeable;

type CopyDeclarations = {
    readonly copyFor: (type: PrimitiveType) => readonly string[] | undefined;
};

type UnreadCopy = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /**
     * Its string-valued props, in the order the node carries them.
     */
    readonly props: readonly string[];
};

type UnspokenCopy = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** The declared copy props holding a non-string value, in declaration order. */
    readonly props: readonly string[];
};

type NodeCopy = {
    /**
     * In reading order: each element's own declared copy before its children's,
     * because a stat's label is above the things under it and a card's title is
     * above its body. Blank and whitespace-only values are left out — a caller
     * composing a sentence wants words, and an empty string is not one.
     */
    readonly words: readonly string[];
    /** What this reading could not see. Empty when every type under it declared. */
    readonly unread: readonly UnreadCopy[];
    /** What it was told to read and could not. Empty when every declared copy prop held a string. */
    readonly unspoken: readonly UnspokenCopy[];
};

type PrimitiveDefinition<TProps extends JsonObjectView = JsonObject, TText extends string = never, TBehaviour extends BehaviourName = never> = {
    readonly type: string;
    readonly description: string;
    readonly props: ZodType<TProps, ZodTypeDef, unknown>;
    readonly slots?: readonly string[];
    /**
     * Declared strings, by key. The keys are inferred, so the component's
     * `loom.text` is typed to exactly what was declared here — an author who
     * reads a key they did not declare finds out at the declaration, which is the
     * same bargain the props schema makes.
     */
    readonly text?: Readonly<Record<TText, string>>;
    /**
     * `"always"` for a primitive that is a target however it is configured, or
     * `{ whenProps }` naming the props that make it one — `href` on a card, which
     * is a plain surface without it. The named props must be props the schema
     * declares; the registry refuses a declaration that names one it does not, so
     * a renamed prop cannot leave this quietly pointing at nothing.
     */
    readonly interactive?: InteractiveWhen;
    /**
     * `true` for a primitive whose job includes sending what it collected. It
     * takes no conditional form, unlike `interactive`: a card is a target only
     * when the tree gives it an `href`, but a form is a form, and a primitive
     * that posts under one prop value and not another is two primitives.
     */
    readonly submits?: boolean;
    /**
     * The props whose values this primitive puts in an `iframe` — `["src"]` on an
     * embed. Empty for everything else, which is every other primitive there is.
     */
    readonly frames?: readonly string[];
    /**
     * The controls this primitive takes from the runtime's closed behaviour
     * vocabulary — `["copy"]` on a code panel. Optional, and empty for almost
     * everything: a Loom page is data, and a behaviour is the exception that has
     * to be asked for by name.
     */
    readonly behaviours?: readonly TBehaviour[];
    /**
     * The prop each control takes its name from — `{ present: "label" }` on a
     * dialog whose trigger carries the page's own call to action.
     */
    readonly names?: Readonly<Partial<Record<TBehaviour, string>>>;
    /**
     * What part this primitive plays — `"heading"` on anything a reader takes as
     * the title of what follows, whatever it is called. Optional, and absent on
     * almost everything: most primitives are an arrangement or a surface and play
     * no part a consumer asks about categorically.
     */
    readonly role?: PrimitiveRole;
    /**
     * The props whose values a reader reads as words — `["value", "label",
     * "caption"]` on a stat, `[]` on an arrangement that shows none of its own.
     */
    readonly copy?: readonly string[];
    /**
     * The binding names this primitive reads an answer under — `["entries"]` on a
     * feed, `[]` on everything that draws only what the tree wrote.
     */
    readonly reads?: readonly BindingDeclaration[];
    /**
     * The shape of answer this primitive can read, per binding name it reads —
     * `{ entries: z.array(z.unknown()) }` on a feed, `{ value: figureSchema }` on
     * a figure.
     */
    readonly expects?: Readonly<Record<string, ZodTypeAny>>;
    /**
     * What this primitive made of each answer it was given: the rows it found and
     * the rows it placed. The walk reports the ones where those differ.
     */
    readonly unshown?: UnshownDeclaration;
    readonly component: LoomPrimitive<TProps, TText, TBehaviour>;
};

type PrimitiveEntry = {
    readonly type: string;
    readonly description: string;
    readonly slots: readonly string[];
    readonly component: LoomPrimitive;
    readonly declaredProps: readonly CataloguedProp[] | undefined;
    /**
     * The props whose accepted values can be listed, so the conformance probe can
     * ask the primitive what it does under each one rather than under whichever
     * shape it happens to take with no props at all. Empty for the
     * primitive whose rendering does not turn on a closed choice, which is most.
     */
    readonly choices: readonly ClosedChoice[];
    /** Declared strings, keys erased alongside the props type. Empty when none. */
    readonly text: PrimitiveText<string>;
    /** Absent for the ordinary primitive, which is not a target at all. */
    readonly interactive: InteractiveWhen | undefined;
    /** `false` for the ordinary primitive, which sends nothing anywhere. */
    readonly submits: boolean;
    /** Declared framable prop names, still raw: the registry is what checks them. */
    readonly frames: readonly string[];
    /** Declared behaviour names, still raw: the registry is what checks them. */
    readonly behaviours: readonly string[];
    /**
     * Which prop names which control, still raw: the registry is what checks that
     * both halves of each pair exist. Empty for the primitive that named none,
     * which is almost all of them.
     */
    readonly names: Readonly<Record<string, string>>;
    /**
     * The declared role, still raw: the registry is what checks it, for the same
     * reason it checks a behaviour name. `undefined` for the primitive that plays
     * no part a consumer asks about, which is most of them.
     */
    readonly role: string | undefined;
    /**
     * Declared copy prop names, still raw: the registry is what checks them.
     * `undefined` is carried through rather than defaulted to `[]`, because the
     * two mean different things here and all the way out to `copyIn`.
     */
    readonly copy: readonly string[] | undefined;
    /**
     * Declared binding names, still raw: the registry is what checks them.
     * `undefined` is carried through rather than defaulted to `[]`, because the
     * two mean different things here and all the way out to the render walk.
     */
    readonly reads: readonly BindingDeclaration[] | undefined;
    /**
     * The declared answer shapes, erased to validators and keyed by declared
     * name. `undefined` for the primitive that declared none, which is every
     * primitive that reads no data and most of the ones that do.
     */
    readonly expects: Readonly<Record<string, AnswerExpectation>> | undefined;
    /**
     * The declared reading of this node's answers, or `undefined` where the author
     * has not said. Nothing to check at registration — there are no names in it
     * and no props it could name — so it is carried straight through.
     */
    readonly unshown: UnshownDeclaration | undefined;
    readonly validate: (props: JsonObject) => PropsVerdict;
};

type DerivedPairing = {
    readonly foreground: PaletteSlot;
    readonly background: PaletteSlot;
    readonly basis: PairingBasis;
    /** The primitives that produce it, so a failure names components rather than two slot ids. */
    readonly types: readonly PrimitiveType[];
};

type ChildGround = {
    readonly ground: PaletteSlot;
    readonly types: readonly PrimitiveType[];
};

type UnprobedProps = {
    readonly type: PrimitiveType;
    readonly props: readonly string[] | undefined;
};

type RegistryPairings = {
    readonly pairings: readonly DerivedPairing[];
    /** Inks a primitive sets without painting a ground of its own. */
    readonly floating: readonly PaletteSlot[];
    /** Every ground a primitive places children on, whether or not the ramp is held to it. */
    readonly childGrounds: readonly ChildGround[];
    /**
     * Grounds children land on that the text ramp is not held to. Not a failure:
     * `accent` is here because `loom.action` fills it and answers the ink itself.
     * It is reported because a *new* ground appearing here is the signal that
     * either a primitive is painting somewhere unconsidered or the declared list
     * has fallen behind the library — the same drift this module exists to catch,
     * one level up.
     */
    readonly groundsOutsideTheRamp: readonly ChildGround[];
    /** The probe could not answer — neither a pass nor a failure. */
    readonly notProbeable: readonly PrimitiveType[];
    /**
     * Where this derivation stops seeing, by primitive. Only primitives with at
     * least one such prop appear, so an empty list is a real claim: nothing in
     * this registry hides an element behind a prop the probe cannot set.
     */
    readonly unprobedProps: readonly UnprobedProps[];
};

type RegisteredPrimitive = {
    readonly type: PrimitiveType;
    readonly description: string;
    readonly slots: readonly SlotName[];
    readonly component: LoomPrimitive;
    readonly declaredProps: PrimitiveEntry["declaredProps"];
    /** The props the conformance probe can vary, from the declared schema. */
    readonly choices: PrimitiveEntry["choices"];
    /** Declared strings in the author's language, before any dictionary. */
    readonly text: PrimitiveText<string>;
    /** Whether it renders a target, and what makes it one. Absent for most. */
    readonly interactive: InteractiveWhen | undefined;
    /** Whether its author says it posts. `false` for most. */
    readonly submits: boolean;
    /** The props it puts in a frame. Empty for all but one primitive. */
    readonly frames: readonly string[];
    /** The controls it takes from the runtime's vocabulary. Empty for most. */
    readonly behaviours: readonly BehaviourName[];
    /**
     * The prop each of those controls is named by, where its author said so
     *. Empty for almost every primitive that takes a control at all: a
     * control's name is normally a string the primitive declared, and this is the
     * exception for the trigger whose words are the page's.
     */
    readonly names: ControlNameProps;
    /** What part it plays. `undefined` for most, which play none. */
    readonly role: PrimitiveRole | undefined;
    /**
     * The props a reader reads as words. `undefined` where the primitive
     * has not said, which is not the same answer as `[]` and is not rounded to
     * it.
     */
    readonly copy: readonly string[] | undefined;
    /**
     * The binding names it reads an answer under, each either a name or
     * the prop that gives one. `undefined` where the primitive has not
     * said, which is not the same answer as `[]` and is not rounded to it — the
     * walk reports under the first and stays quiet under the second.
     */
    readonly reads: readonly BindingDeclaration<BindingName>[] | undefined;
    /**
     * The shape of answer it can read under each of those names, erased to
     * a validator. `undefined` where the primitive has declared none, which here
     * is the same answer as declaring an empty map — unlike `reads` and `copy`,
     * because there is no claim in the absence to tell apart: a name with no
     * expectation is handed its answer unchecked either way.
     */
    readonly expects: Readonly<Record<string, AnswerExpectation>> | undefined;
    /**
     * Its own reading of the answers it was given. `undefined` where the
     * author has not said, which here is the same answer as declaring one that
     * reports nothing — unlike `copy` and `reads`, because there is no emptiness
     * to distinguish: a reading is made per answer at render time, and a primitive
     * that has said nothing about its answers is reported on by nothing.
     */
    readonly unshown: UnshownDeclaration | undefined;
    readonly validate: (props: JsonObject) => PropsVerdict;
};

type RegistryError = {
    readonly code: "invalid-primitive-type";
    readonly type: string;
} | {
    readonly code: "invalid-slot-name";
    readonly type: string;
    readonly slot: string;
} | {
    readonly code: "invalid-text-key";
    readonly type: string;
    readonly key: string;
} | {
    readonly code: "blank-text";
    readonly type: string;
    readonly key: string;
} | {
    readonly code: "undeclared-interactive-prop";
    readonly type: string;
    readonly prop: string;
} | {
    readonly code: "undeclared-frame-prop";
    readonly type: string;
    readonly prop: string;
} | {
    readonly code: "undeclared-copy-prop";
    readonly type: string;
    readonly prop: string;
} | {
    readonly code: "unknown-behaviour";
    readonly type: string;
    readonly behaviour: string;
} | {
    readonly code: "unnamed-behaviour";
    readonly type: string;
    readonly behaviour: string;
    readonly key: string;
} | {
    readonly code: "undeclared-interactive-behaviour";
    readonly type: string;
    readonly behaviour: string;
} | {
    readonly code: "unpaired-behaviour";
    readonly type: string;
    readonly behaviour: string;
    readonly requires: string;
} | {
    readonly code: "undeclared-named-behaviour";
    readonly type: string;
    readonly behaviour: string;
