type LivePages = {
    /** The live pages, by the id of the page each one is. */
    readonly pages: ReadonlyMap<TreeId, LoomTree>;
    /** The entity tag the door gave for exactly these pages, if it gave one. */
    readonly tag: string | undefined;
    /** When the door last answered, whether it answered pages or `304`. */
    readonly pulledAt: number | undefined;
    /** When these pages arrived, which is older than `pulledAt` after a `304`. */
    readonly freshAt: number | undefined;
    /** Failed pulls since the last one the door answered. Zero while current. */
    readonly failures: number;
};

type SitePullFailure = {
    readonly reason: "unconfigured" | "unreachable" | "expired" | "refused" | "unreadable";
    readonly detail: string;
    readonly status?: number;
};

type SitePullOutcome = {
    readonly kind: "fresh";
    readonly pages: readonly LoomTree[];
    readonly tag: string | undefined;
} | {
    readonly kind: "unchanged";
} | {
    readonly kind: "failed";
    readonly failure: SitePullFailure;
};

type PullFetch = (url: string, init: {
    readonly method: "GET";
    readonly headers: Readonly<Record<string, string>>;
    readonly signal: AbortSignal;
    readonly cache: "no-store";
}) => Promise<Response>;

type PullLivePagesOptions = {
    /**
     * Where this project's Loom deployment is, as an origin — `https://loom.example.com`.
     * The path is this module's, so a project's configuration never carries one.
     */
    readonly deployment: string;
    /**
     * The project's public key, the one its pages already post signals with
     *. Opaque here: what a key may look like is the door's to say, and a
     * second spelling of the rule in the client would be a second place to be
     * wrong.
     */
    readonly key: string;
    /** How long to wait for the door. `DEFAULT_PULL_CEILING_MS` when unset. */
    readonly ceilingMs?: number;
    /** `globalThis.fetch` unless a host hands over its own. */
    readonly fetch?: PullFetch;
};

type StartPullingOptions = PullLivePagesOptions & {
    /** How long between pulls. `DEFAULT_PULL_INTERVAL_MS` when unset. */
    readonly intervalMs?: number;
    /** How long `ready()` waits on a silent Loom. `DEFAULT_FIRST_WAIT_MS` when unset. */
    readonly firstWaitMs?: number;
    /**
     * Told of every outcome, after what is held has moved.
     */
    readonly onOutcome?: (outcome: SitePullOutcome, held: LivePages) => void;
    readonly now?: () => number;
    readonly schedule?: PullSchedule;
};

type LivePullLoop = {
    readonly ready: () => Promise<LivePages>;
    readonly held: () => LivePages;
    readonly pullNow: () => Promise<SitePullOutcome>;
    readonly stop: () => void;
};

type ActedCounts = {
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
