        readonly from?: number;
        readonly to?: number;
    }) => Promise<Result<StoredActed, ReaderSignalStoreError>>;
};

type ActedRate = {
    /**
     * What readers did per hundred page views in the range, or `null` where there
     * is no quotient to take.
     */
    readonly per100: number | null;
    /** The same figure for the period before, or `null` on the same terms. */
    readonly was: number | null;
    /** The quotient of the two rates, or why there is none (`ratios.ts`). */
    readonly ratio: Ratio;
};

type ActedRateReading = {
    readonly acted: ActedReading;
    readonly arrivals: ArrivalReading;
    readonly rate: ActedRate;
};

type ActionStanding =
/** A row credits it with readers who acted inside it, or with uses of its own. */
"acted"
/**
 * Readers reached it, it has an inside, and nothing happened in or on it.
 */
 | "untouched"
/**
 * Nothing can be said.
 */
 | "unknown";

type PartAction = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** null at the root. */
    readonly parentId: NodeId | null;
    /**
     * What this window can say about whether readers acted on this part.
     */
    readonly standing: ActionStanding;
    /**
     * Whether any element part of this revision names it as a parent.
     */
    readonly bearsParts: boolean;
    /** Distinct page views that reported it coming into view, or `undefined` where no row named it. */
    readonly reached: number | undefined;
    /**
     * Distinct page views in which a reader used something strictly inside it
     *, or `undefined` where no row named it.
     */
    readonly within: number | undefined;
    /**
     * `within ÷ reached`, in `[0, 1]`, or `undefined`.
     */
    readonly share: number | undefined;
    /**
     * Presses, opens, closes and submissions filed against this part itself,
     * added.
     */
    readonly uses: number;
    /** The four occurrence counters, kept apart. `0` each where no row named it. */
    readonly counts: {
        readonly activations: number;
        readonly opens: number;
        readonly closes: number;
        readonly completions: number;
    };
    /**
     * `uses ÷ reached`, or `undefined` where nothing was used or nobody reached
     * it.
     */
    readonly usesPerReader: number | undefined;
    /**
     * `closes ÷ opens`, or `undefined` where nothing was opened.
     */
    readonly shutAgain: number | undefined;
};

type PageAction = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The page's view floor, carried through from the reading unchanged.
     */
    readonly views: number;
    /** Every element part of the revision, in reading order. */
    readonly parts: readonly PartAction[];
    readonly standings: Readonly<Record<ActionStanding, number>>;
    /**
     * The root, which is the one page-wide headcount this subsystem has.
     */
    readonly whole: PartAction | null;
    /**
     * The part the most readers reached and did nothing in: most reached, then
     * first in reading order.
     */
    readonly mostIgnored: PartAction | null;
    /**
     * Parts with no element parts under them, whose share is withheld for the
     * structural reason.
     */
    readonly leaves: number;
    /**
     * Whether the window holds uses and credits them to nobody.
     */
    readonly unwalked: boolean;
};

type ActionMovement =
/**
 * Readers reached it and did nothing in it, and now they do something — the
 * sentence a change to a band nobody uses is made for.
 */
"taken-up"
/** Readers did something in it and now they reach it and do nothing. */
 | "abandoned"
/**
 * Reached and untouched before, reached and untouched now — the asks a change
 * did not fix.
 */
 | "still-untouched"
/** Readers did something in it before and after. */
 | "held"
/**
 * One of the two windows cannot say whether readers acted on it.
 */
 | "unknown";

type InsideMovement =
/** It bore element parts in both revisions, so its share means the same thing on both sides. */
"kept"
/**
 * It was a leaf and now bears element parts, so it has a share where its share
 * was withheld.
 */
 | "gained"
/** It bore element parts and is now a leaf, so a share that was a measurement is withheld. */
 | "lost"
/** A leaf in both revisions: its share is withheld on both sides and its standing is `unknown` on both. */
 | "none";

type ComparedAction = {
    readonly nodeId: NodeId;
    /** The later revision's type, which is the page somebody is looking at. */
    readonly type: PrimitiveType;
    /** The later revision's role, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** The whole of what the earlier window said about it. */
    readonly was: PartAction;
    /** The whole of what the later window said about it. */
    readonly now: PartAction;
    readonly movement: ActionMovement;
    /** What the change did to whether a share of this part is measurable at all. */
    readonly inside: InsideMovement;
    /**
     * `now.share ÷ was.share`, with the reason named where there is no quotient
     *.
     */
    readonly shareRatio: Ratio;
    /**
     * `now.usesPerReader ÷ was.usesPerReader`, with a nought a side withheld
     * restored first.
     */
    readonly usesRatio: Ratio;
};

type ActionChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     */
    readonly audiences: ComparedAudiences;
    /** The two readings of what readers did that this comparison is made of. */
    readonly readings: {
        readonly was: PageAction;
        readonly now: PageAction;
    };
    /**
     * Every part both revisions have that a row named on either side, in the
     * **later** reading order.
     */
    readonly compared: readonly ComparedAction[];
    /**
     * Parts only the later revision has, as the later window read them, in its
     * reading order.
     */
    readonly added: readonly PartAction[];
    /** Parts only the earlier revision had, as the earlier window read them, in its reading order. */
    readonly removed: readonly PartAction[];
    /** Compared parts by what happened to the standing. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<ActionMovement, number>>;
    /** Compared parts by what the change did to their shape. The four add to {@link compared}'s length. */
    readonly insides: Readonly<Record<InsideMovement, number>>;
    /**
     * The root, compared against itself across the two revisions.
     */
    readonly whole: ComparedAction | null;
    /**
     * The ask the change got answered: `taken-up`, most readers reached it in the
     * later window, then first in the later reading order.
     */
    readonly mostTakenUp: ComparedAction | null;
    /** The ask the change lost, on the same terms. */
    readonly mostAbandoned: ComparedAction | null;
    /**
     * The parts readers reached and did nothing in, before and after — most
     * reached now first, then in the later reading order.
     */
    readonly stillUntouched: readonly ComparedAction[];
    /** Why there is no comparison of the reading, or `null` where there is one. */
    readonly silence: ActionChangeSilence | null;
};

type AgendaRow = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the readings named none.
     */
    readonly audienceId: AudienceId | null;
    readonly work: AgendaWork;
    /**
     * Whether a fault reaches the loss the order of falls ranked this page by.
     */
    readonly spoiled: boolean;
    /**
     * Whether a fault reaches the loss the order of conversions ranked this page
     * by.
     */
    readonly spoiledConversion: boolean;
    /** The page as the order of falls has it, carried whole and unchanged. */
    readonly order: RankedPage;
    /** The page as the order of conversions has it, carried whole and unchanged. */
    readonly conversion: LeakingPage;
    /** The page as the health reading has it, carried whole and unchanged. */
    readonly health: PageHealth;
    /**
     * The page as the order of **places** has it, carried whole and unchanged, or
     * `null` where that order has no reading of this page.
     */
    readonly unread: PageUnread | null;
};

type DeploymentAgenda = {
    /**
     * What this fix-list is about, read before any row of it.
     */
    readonly subject: AgendaSubject;
    /**
     * Every page all three readings named, by tree id and newest revision first.
     */
    readonly rows: readonly AgendaRow[];
    /**
     * Pages whose **reading** falls, worst first, in the order of falls' own
     * order.
     */
    readonly page: readonly AgendaRow[];
    /**
     * Pages whose **asks** leak, worst first, in the order of conversions' own
     * order.
     */
    readonly converting: readonly AgendaRow[];
    /**
     * Pages whose collection to repair, worst first, in the health reading's own
     * order: the priced faults by the readers each costs, then the ones the door
     * cannot price.
     */
    readonly collection: readonly AgendaRow[];
    /**
     * Pages an order ranked and a fault spoiled — a **slice** of
     * {@link DeploymentAgenda.collection} and not a further list, so nothing here
     * is counted twice.
     */
    readonly contested: readonly AgendaRow[];
    /**
     * The one thing to do first, or `null` where the three readings ask for
     * nothing.
     */
    readonly first: AgendaRow | null;
    /** How many pages ask for each kind of work, over every row. */
    readonly work: Readonly<Record<AgendaWork, number>>;
    /**
     * Distinct trees across the rows, which is not the number of pages.
     */
    readonly trees: number;
    /**
     * Rows one reading named and the other did not, which is two windows handed
     * in as one.
     */
    readonly unpaired: {
        /** Rows the order of falls named that some other reading has no page for. */
        readonly order: number;
        /** Rows the health reading named that some other reading has no page for. */
        readonly health: number;
        /**
         * Rows the order of conversions named that some other reading has no page
         * for.
         */
        readonly conversion: number;
        /**
         * Pages the order of places named that no row of this fix-list carries.
         */
        readonly unread: number;
    };
    /**
     * Readings of a page beyond the first, on any side, which were dropped.
     */
    readonly duplicated: number;
};

