};

type HourlyBucket = {
    readonly hour: number;
    readonly count: number;
    readonly whole: boolean;
};

type HourlyFill = {
    readonly hours: readonly HourlyBucket[];
    readonly total: number;
    readonly clipped: boolean;
};

const hourlySeriesOf: <Row extends {
    readonly hour: number;
}>(rows: readonly Row[], begins: number | undefined, range: ArrivalRange, count: (row: Row) => number, options?: ArrivalSeriesOptions) => HourlyFill

type ArrivalChange = {
    readonly range: ArrivalRange;
    /** The equal-length period the comparison is against, which is {@link arrivalRangeBefore}. */
    readonly before: ArrivalRange;
    readonly views: number;
    /**
     * Page views in the earlier period, or `null` where counting had not begun
     * when it started.
     */
    readonly was: number | null;
    /**
     * The quotient, or why there is none (`ratios.ts`).
     */
    readonly ratio: Ratio;
};

type ArrivalReadingRequest = {
    readonly range: ArrivalRange;
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /** Absent reads every audience, whose arrivals then add. */
    readonly audience?: AudienceId;
    /** Absent reads every revision, whose arrivals then add. */
    readonly revision?: number;
    /** Now, where the caller has it, so the hour in progress is marked as one. */
    readonly now?: number;
};

type ArrivalCounterHandle = {
    readonly arrivals: (request?: {
        readonly treeId?: TreeId;
        readonly audience?: AudienceId;
        readonly revision?: number;
        readonly from?: number;
        readonly to?: number;
    }) => Promise<Result<StoredArrivals, ReaderSignalStoreError>>;
};

type ArrivalReading = {
    readonly series: ArrivalSeries;
    readonly change: ArrivalChange;
};

type TurnedAwayTally<TReason extends string = string> = {
    readonly reason: TReason;
    /** Deliveries turned away for this reason, cumulative since the counter existed. */
    readonly refused: number;
    /** When the newest of them was turned away, in epoch milliseconds. */
    readonly lastAt: number;
    /**
     * The site the newest of them came from, as an origin, or `null` where it
     * named none.
     */
    readonly lastOrigin: string | null;
};

type NewestTurnedAway<TReason extends string = string> = {
    readonly reason: TReason;
    readonly origin: string | null;
    /** When it was turned away, in epoch milliseconds, as the counter holds it. */
    readonly atMs: number;
    /**
     * How long before the instant handed in it was turned away, or `null` where
     * no instant was.
     */
    readonly sinceMs: number | null;
};

type ArrivalStandingName =
/**
 * Nothing offered a count of what the door turned away, so the question
 * cannot be answered either way.
 */
"unasked"
/**
 * Nothing has been collected and nothing has been turned away.
 */
 | "silent"
/**
 * Nothing has been collected and deliveries have been turned away.
 */
 | "turned-away"
/** Something has been collected and nothing has been turned away. */
 | "collecting"
/**
 * Something has been collected and deliveries have been turned away.
 */
 | "mixed";

type ArrivalStanding<TReason extends string = string> = {
    readonly standing: ArrivalStandingName;
    /**
     * Revisions anything at all was collected about, which is **not** a count of
     * readers.
     */
    readonly collected: number;
    /**
     * Page views counted at the door across every revision read, added.
     */
    readonly arrivals: number;
    /**
     * Deliveries turned away, added across the reasons, or `null` where nothing
     * offered a count.
     */
    readonly refused: number | null;
    /** The newest delivery turned away, or `null` where none was. */
    readonly newest: NewestTurnedAway<TReason> | null;
    /**
     * Tallies beyond the first for one reason, dropped.
     */
    readonly duplicated: number;
};

type AudienceScoped = {
    readonly audienceId: AudienceId;
};

type MaybeAudienceScoped = {
    readonly audienceId?: AudienceId;
};

type SideOfAudience = {
    /** `null` or absent where nothing recorded which audience the window was of. */
    readonly audienceId?: AudienceId | null;
};

type ReadingOfAudience = SideOfAudience & {
    readonly treeId: TreeId;
    readonly revision: number;
};

type AudienceScope =
/**
 * One population: the audience asked for, or the only one the window named.
 */
{
    readonly reading: "one";
    readonly audienceId: AudienceId;
    /** What the window named, which is not what was asked for. */
    readonly audiences: readonly AudienceId[];
}
/**
 * Nothing in the window named an audience, so it is one population by
 * construction and is read whole.
 */
 | {
    readonly reading: "unlabelled";
    readonly audienceId: null;
    readonly audiences: readonly [];
}
/**
 * Two or more forms, and the asking named none of them.
 */
 | {
    readonly reading: "mixed";
    readonly audienceId: null;
    readonly audiences: readonly AudienceId[];
};

type ReadOfAudience = {
    readonly audienceId: AudienceId | null;
    readonly audiences: readonly AudienceId[];
};

type AudienceWindow<R> = {
    readonly audience: AudienceId;
    readonly rows: readonly R[];
};

type PageForm = {
    readonly treeId: TreeId;
    readonly audienceId: AudienceId | null;
};

type ComparedAudiences = {
    readonly was: AudienceId | null;
    readonly now: AudienceId | null;
};

type ComparedPopulations = {
    /** The audiences the earlier window's forms named. `[]` where none did. */
    readonly was: readonly AudienceId[];
    /** The audiences the later window's forms named, by the same rule. */
    readonly now: readonly AudienceId[];
};

type SideOfForm = ReadOfAudience & {
    readonly treeId: TreeId;
    readonly revision: number;
};

type FormPair<R> = {
    readonly pairing: "paired";
    /** The side whose audience id sorts lower. */
    readonly one: R;
    readonly other: R;
    /** The two names, already in the same order as the two sides. */
    readonly audiences: {
        readonly one: AudienceId;
        readonly other: AudienceId;
    };
} | {
    readonly pairing: "refused";
    /** The lower-sorting side, or the first argument where no pair of names stands. */
    readonly one: R;
    readonly other: R;
    readonly refusal: FormPairRefusal;
};

type VisibilityObserver = {
    readonly observe: (element: Element) => void;
    readonly disconnect: () => void;
};

type VisibilityEntry = {
    readonly target: Element;
    readonly visible: boolean;
};

type ReaderSignalTypes = readonly string[] | {
    readonly [Kind in ReaderSignalKind]?: readonly string[];
};

type ReaderSignalOptions = {
    /** Called with every batch. A throw or rejection here is contained and never reaches the page. */
    readonly send?: (batch: ReaderSignalBatch) => void | Promise<void>;
    /** Which kinds to broadcast. Every kind when absent. */
    readonly kinds?: readonly ReaderSignalKind[];
    /**
     * Which primitive types to broadcast about. Every addressed type when absent.
     */
    readonly types?: ReaderSignalTypes;
    /** How often a batch is delivered. Five seconds when absent. */
    readonly flushEveryMs?: number;
    /**
     * How the broadcaster learns what is on screen. The browser's
     * `IntersectionObserver` when absent; a test passes its own.
     */
    readonly observeVisibility?: ObserveVisibility;
    /**
     * Whether a delegated signal carries the addressed nodes it happened inside.
     * On when absent.
     */
    readonly within?: boolean;
    /** The clock. `Date.now` when absent. */
    readonly now?: () => number;
    /**
     * Where the view key's randomness comes from. The browser's
     * `crypto.getRandomValues` when absent; a test passes its own so it can name
     * the key it expects.
     */
    readonly random?: RandomBytes;
};

type ReaderSignalBroadcast = {
    /** Deliver whatever has been gathered, now. */
    readonly flush: () => void;
    /** Deliver what is left and stop observing. Safe to call twice. */
    readonly stop: () => void;
};

type ReaderSignalBroadcastError = {
    /** The root carries no tree id or revision — the page was not rendered with `addressed: true`. */
    readonly code: "unaddressed";
    readonly detail: string;
};

type StopSide = {
    /** Views that reached the first of the pair, which is the denominator of `share`. */
    readonly reached: number;
    /** Views that reached the first and not the second. Zero where none did. */
    readonly lost: number;
    /** `lost ÷ reached`, in `[0, 1]`. Zero is a pair nobody stopped at. */
    readonly share: number;
};

type ComparedStop = {
    /** The part they reached. */
    readonly after: NodeId;
    /** The next part in the run, which fewer reached. */
    readonly before: NodeId;
    /** The parent whose run they are both steps of, which is the same node in both readings. */
    readonly parentId: NodeId;
    readonly was: StopSide;
    readonly now: StopSide;
    /**
     * `was.share − now.share`: the share of readers that no longer stop here.
     */
    readonly improvement: number;
    /**
     * The smallest share one reader could move, on whichever side counted fewer.
     */
    readonly resolution: number;
    /**
     * Whether `improvement` is at least one reader's worth on the coarser side.
     */
    readonly beyondOneReader: boolean;
    /**
     * `improvement × now.reached`: the readers the change no longer loses here, at
     * the volume the page has now.
     */
    readonly readersKept: number;
};

type IncomparablePair = {
    readonly after: NodeId;
    readonly before: NodeId;
    readonly parentId: NodeId;
    /** Which reading this pair is from, and therefore which reading `reached` and `share` are off. */
    readonly side: "was" | "now";
    readonly fate: PairFate;
    readonly reached: number;
    readonly share: number;
};

type PartsChanged = {
    /** Element nodes in both revisions, {@link PartsChanged.moved} among them. */
    readonly shared: number;
    /** In the later revision and not the earlier one, in reading order. */
    readonly added: readonly NodeId[];
    /** In the earlier revision and not the later one, in reading order. */
    readonly removed: readonly NodeId[];
    /** Shared parts whose parent is a different node, in reading order. */
    readonly moved: readonly NodeId[];
    /**
     * Shared parts whose own words are not the words they were, in reading order.
     */
    readonly reworded: readonly NodeId[];
    /**
     * Shared parts whose words were the same as far as this reading could see, and
     * where something about them went unread on one side or the other.
     */
    readonly unreadable: number;
};

type ReadingChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     */
    readonly audiences: ComparedAudiences;
    /**
     * The two progress readings this comparison is made of.
     */
    readonly progress: {
        readonly was: ReadingProgress;
        readonly now: ReadingProgress;
    };
    readonly parts: PartsChanged;
    /** Every pair both readings could measure, in the earlier reading's reading order. */
    readonly stops: readonly ComparedStop[];
    /** Every pair only one of them could, each once, with the reason. */
    readonly incomparable: readonly IncomparablePair[];
    /**
     * The pair the change keeps most readers at, among those beyond one reader.
     */
    readonly mostKept: ComparedStop | null;
    /** The pair it loses most readers at, on the same terms. Null where none worsened. */
    readonly mostLost: ComparedStop | null;
    /** Why nothing was compared, or `null` where something was. */
    readonly silence: ChangeSilence | null;
};

type CollectionRequest = {
    readonly windowMs?: number;
    /**
     * The funnels this deployment asks about. Absent means none — a pair is a
     * question somebody wrote down, and rollup does not invent questions.
     */
    readonly pairs?: readonly FunnelPair[];
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type CollectionPlan = {
    /** Old enough to count, in ascending `seq`. */
    readonly ripe: readonly ReceivedBatch[];
    /** The position to forget below, once the counters are durable. `null` when nothing is ripe. */
    readonly before: number | null;
    /** Seen by this scan and too young. A floor rather than a total — the scan stops at the first. */
    readonly waiting: number;
};

type CollectionSummary = {
    readonly counted: number;
    readonly tallies: number;
    readonly funnels: number;
    /**
     * Hourly rows this run wrote for what readers did (`acted.ts`).
     */
    readonly acted: number;
    /** Distinct page views the window held. */
    readonly views: number;
    /**
     * Batches that carried no view key, whose occurrences counted and whose views
     * did not. A rate shown without saying which denominator it used is the
     * failure mode here, so the number travels with the run that produced it.
     */
    readonly uncorrelated: number;
    /**
     * Of the batches counted, how many were a repeat of one already folded in
     * this window and were therefore folded once (`rollup.ts`).
     */
    readonly redelivered: number;
    /**
     * How old the oldest **uncounted** delivery the scan found was, in
     * milliseconds, at the instant this run was taken.
     */
    readonly oldestMs: number;
};

type CollectionOutcome = {
    readonly outcome: "collected";
    readonly summary: CollectionSummary;
    /**
     * Rows this run marked as counted.
     */
    readonly recorded: number;
    /** The scan filled its limit with ripe batches, so another run has work now. */
    readonly more: boolean;
}
/** Nothing is old enough yet, which is the ordinary answer on a quiet deployment. */
 | {
    readonly outcome: "nothing-ripe";
    readonly waiting: number;
}
/**
 * The counters took the window and the journal would not record it.
 */
 | {
    readonly outcome: "counted-not-recorded";
    readonly summary: CollectionSummary;
    readonly before: number;
    readonly error: ReaderSignalStoreError;
}
/** The window was not usable. Nothing was read, counted or marked. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
}
/** Read or write failed before anything became durable. Nothing was marked. */
 | {
    readonly outcome: "unavailable";
    readonly error: ReaderSignalStoreError;
};

type ConversionStanding =
/** In the order, by the readers it loses between the two ends of its sharpest ask. */
"ranked"
/**
 * Every reader who reached one of its asks went on to answer it.
 */
 | "unleaked"
/**
 * Nothing asks this version of the page for anything.
 */
 | "unasked" | ConversionSilence;

type LeakingPage = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: ConversionStanding;
    /** Page views counted at the door, exact, or `null` where this revision has no row. */
    readonly opened: number | null;
    /** This page's own straddle rate, which is what scales its loss. */
    readonly inflation: number | null;
    /** How many questions this revision is asked, as the reading read them. */
    readonly questions: number;
    /** Of those, how many name a part this revision no longer has. */
    readonly stalePairs: number;
    /**
     * The ask that loses the most readers between its two ends, carried whole and
     * unchanged.
     */
    readonly at: PairReach | null;
    /** Readers lost between that ask's two ends, as the window's counters have it. */
    readonly lost: number | null;
    /**
     * The same loss on the door's scale, which is the key the order is on, and
     * the **most** that loss could be.
     */
    readonly readers: number | null;
    /**
     * The least that loss could be, given the straddle this page's own door
     * measured.
     */
    readonly readersAtLeast: number | null;
    /**
     * Of the readers who reached that ask, the share that answered it, carried
     * through from the pair unchanged.
     */
    readonly rate: number | null;
};

type DeploymentConversion = {
    /**
     * Every page with a leak and a scale for it, worst first.
     */
    readonly ranked: readonly LeakingPage[];
    /** Every other page, by tree id and newest revision first. */
    readonly unranked: readonly LeakingPage[];
    /** The head of the order, which is the funnel to look at first. */
    readonly worst: LeakingPage | null;
    /**
     * Whether the page named {@link DeploymentConversion.worst} is first however
     * the straddle fell: its floor is at or above every other ranked page's
     * ceiling.
     */
    readonly worstSecure: boolean | null;
    /** How many pages stand in each state, over the ranked and the unranked alike. */
    readonly standings: Readonly<Record<ConversionStanding, number>>;
    /**
     * Distinct trees across every page read, which is not the number of pages.
     */
    readonly trees: number;
    /**
     * Page views counted at the door across the pages handed in, added.
     */
    readonly arrivals: number;
    /**
     * Funnel questions across the pages handed in, added.
     */
    readonly questions: number;
    /** Of those, how many name a part the revision asking them no longer has. */
    readonly stalePairs: number;
    /**
     * Readings of a revision beyond the first, which were dropped.
     */
    readonly duplicated: number;
};

type Passage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** Carried through from the part, so a passage and a part say the same thing. */
    readonly standing: PartStanding;
    /** Distinct page views that reported the part coming into view; `0` where no row named it. */
    readonly readers: number;
    /**
     * The words themselves, in reading order, exactly as the page says them.
     */
    readonly text: readonly string[];
    /** {@link text}, counted. */
    readonly words: number;
    /**
     * Whether this passage is short of words it cannot see.
     */
    readonly floored: boolean;
};

type RoleCopy = {
    /** `null` is the row for parts whose type declared no role. */
    readonly role: PrimitiveRole | null;
    /** Parts of this role that say something, which is the rule {@link CopyReading.passages} applies. */
    readonly passages: number;
    readonly words: number;
    /**
     * Words by the standing of the part saying them. The three add to
     * {@link words}.
     */
    readonly wordsByStanding: Readonly<Record<PartStanding, number>>;
    /**
     * This role's words in parts the window can speak for, which is the
     * denominator of {@link share}.
     */
    readonly spoken: number;
    /**
     * The share of this role's **spoken-for** words at least one reader reached.
     * `null` where the window can speak for none of them.
     */
    readonly share: number | null;
    /** Passages of this role whose words are a floor. */
    readonly floored: number;
};

type CopySilence =
/** The page says nothing that could have been read. */
"wordless"
/** The window held no views of this revision, so there is no reader to be typical of. */
 | "unmeasured"
/**
 * Some part's words are a floor, so a mean of them is neither a count nor a
 * ceiling.
 */
 | "floored"
/**
 * No word of the page is in a part this window can speak for, so there is no
 * word to take a mean over.
 */
 | "unspoken"
/**
 * A part reports more readers than the page has views, which no rollup
 * produces.
 */
 | "inconsistent";

type CopyReading = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** The page's view floor, carried through from the reading unchanged. */
    readonly views: number;
    /**
     * Every word this revision says, counted once.
     */
    readonly words: number;
    /** Words by the standing of the part saying them. The three add to {@link words}. */
    readonly wordsByStanding: Readonly<Record<PartStanding, number>>;
    /**
     * The page's words in parts this window can speak for, which is the
     * denominator of {@link share}.
     */
    readonly spoken: number;
    /**
     * The share of the words **this window can speak for** that at least one
     * reader reached. `null` where there are none of them.
     */
    readonly share: number | null;
    /** Every part that says something, in reading order. */
    readonly passages: readonly Passage[];
    /**
     * Parts that say nothing at all, counted rather than listed.
     */
    readonly silent: number;
    /**
     * The passages no reader reached, most words first and then in reading order.
     */
    readonly unseen: readonly Passage[];
    /** Every role in the vocabulary, then the row for parts that declared none. */
    readonly roles: readonly RoleCopy[];
    /**
     * Passages whose words are a floor, by the standing of the part saying them.
     */
    readonly floored: Readonly<Record<PartStanding, number>>;
    /**
     * The words the typical reader reached, at most. `null` where {@link silence}
     * says why not.
     */
    readonly typical: number | null;
    /**
     * Why a figure is not there, and `null` where both are.
     */
    readonly silence: CopySilence | null;
};

type PassageMovement =
/** Reached on both sides. */
"held"
/** Nobody reached it and now somebody does, which is the sentence a change is made for. */
 | "gained"
/** Somebody reached it and now nobody does. */
 | "lost"
/** Nobody reached it on either side — the words a change did not fix. */
 | "unread"
/**
 * One side cannot be spoken for.
 */
 | "unknown";

type PassageSide = {
    readonly standing: PartStanding;
    /** Distinct page views that reported the part coming into view; `0` where no row named it. */
    readonly readers: number;
    /** That side's page-view floor, carried through so the share below can be checked. */
    readonly views: number;
    /**
     * {@link readers} over {@link views}, and `null` where the window held none.
     */
    readonly reach: number | null;
};

type ComparedPassage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The words, the same number on both sides because they are the same words. */
    readonly words: number;
    /** The text itself, so a passage can be quoted back without a second join. */
    readonly text: readonly string[];
    /**
     * Whether either side's part declares no `copy`, so {@link words} is a floor.
     */
    readonly floored: boolean;
    readonly was: PassageSide;
    readonly now: PassageSide;
    readonly movement: PassageMovement;
    /**
     * The words this passage newly put in front of the average reader:
     * `words × (now.reach − was.reach)`.
     */
    readonly gain: number | null;
};

type RewordedPassage = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The two word counts, which is why there is no single one. */
    readonly words: {
        readonly was: number;
        readonly now: number;
    };
    /** Whether either side declares no `copy`, so its word count is a floor. */
    readonly floored: boolean;
    readonly was: PassageSide;
    readonly now: PassageSide;
    readonly movement: PassageMovement;
};

type WordsWritten = {
    /**
     * Words both revisions say, word for word — the universe every reader figure
     * here is about.
     */
    readonly carried: number;
    /** Words only the later revision says. */
    readonly added: number;
    /**
     * {@link added}, by what the later window said about reaching them. The three
     * add to {@link added}.
     */
    readonly addedByStanding: Readonly<Record<PartStanding, number>>;
    /** Words only the earlier revision says. */
    readonly removed: number;
    /**
     * {@link removed}, by what the earlier window said about reaching them. The
     * three add to {@link removed}.
     */
    readonly removedByStanding: Readonly<Record<PartStanding, number>>;
    /** Words of passages both revisions have and neither says the same way. */
    readonly reworded: {
        readonly was: number;
        readonly now: number;
    };
};

type WordCount = {
    readonly was: number;
    readonly now: number;
    readonly change: number;
};

type CopyChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     */
    readonly audiences: ComparedAudiences;
    /** The two copy readings this comparison is made of. */
    readonly readings: {
        readonly was: CopyReading;
        readonly now: CopyReading;
    };
    /**
     * Every word each revision says, counted once, and the difference.
     */
    readonly words: WordCount;
    /** The census of what the change wrote, with no reader in it. */
    readonly wrote: WordsWritten;
    /**
     * Every passage both revisions say identically, in the **later** reading's
     * reading order.
     */
    readonly compared: readonly ComparedPassage[];
    /** Every passage both revisions have and neither says the same way, in the later order. */
    readonly reworded: readonly RewordedPassage[];
    /** Every passage only the later revision has, in its reading order. */
    readonly added: readonly Passage[];
    /** Every passage only the earlier revision had, in the earlier reading order. */
    readonly removed: readonly Passage[];
    /**
     * Carried words by what happened to the reading of them. The five add to
     * {@link WordsWritten.carried}.
     */
    readonly wordsByMovement: Readonly<Record<PassageMovement, number>>;
    /**
     * Carried passages by the same. The five add to {@link compared}'s length.
     */
    readonly passagesByMovement: Readonly<Record<PassageMovement, number>>;
    /** Carried passages whose words are a floor, which is what `floored` counts. */
    readonly floored: number;
    /**
     * The carried passages nobody reached on either side, most words first and
     * then in the later reading order.
     */
    readonly stillUnseen: readonly ComparedPassage[];
    /**
     * The carried words the average reader got to, before and after. `null` where
     * {@link silence} says why not.
     */
    readonly typical: WordCount | null;
    /**
     * The carried passage the change put most words in front of the average
     * reader, and `null` where none gained any.
     */
    readonly mostGained: ComparedPassage | null;
    /** The carried passage it took most words away from, on the same terms. */
    readonly mostLost: ComparedPassage | null;
    /** Why there is no reader comparison, or `null` where there is one. */
    readonly silence: CopyChangeSilence | null;
};

type DeliverOptions = {
    /** Where to post. {@link DEFAULT_READER_SIGNAL_PATH} when absent. */
    readonly url?: string;
    /** The browser's, when absent. A test passes its own. */
    readonly beacon?: SendBeacon | null;
    /** `fetch` with `keepalive`, when absent. */
    readonly post?: PostBatch;
};

type RankStanding =
/** In the order, with a fall and a scale for it. */
"ranked"
/**
 * Read, scalable, and losing nobody anywhere on the page.
 */
 | "unbroken" | DeploymentSilence;

type RankedPage = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: RankStanding;
    /**
     * The window's view floor, carried through from the reading unchanged.
     */
    readonly views: number;
    /**
     * Page views counted at the door, exact, or `null` where this revision has no
     * row.
     */
    readonly opened: number | null;
    /** This page's own straddle rate, which is what scales its loss. */
    readonly inflation: number | null;
    /** The sharpest fall on the page, where it has one. */
    readonly at: ReadingStop | null;
    /** Readers lost at that fall, as the window's counters have it. */
    readonly lost: number | null;
    /**
     * The same loss on the door's scale, which is the key the order is on.
     */
    readonly readers: number | null;
    /**
     * The fall as a share of the readers who reached the part before it, carried
     * through unchanged.
     */
    readonly share: number | null;
};

type DeploymentReading = {
    /**
     * Every page with a fall and a scale for it, worst first.
     */
    readonly ranked: readonly RankedPage[];
    /** Every other page, by tree id and newest revision first. */
    readonly unranked: readonly RankedPage[];
    /** The head of the order, which is the page to fix first. */
    readonly worst: RankedPage | null;
    /** How many pages stand in each state, over the ranked and the unranked alike. */
    readonly standings: Readonly<Record<RankStanding, number>>;
    /**
     * Distinct trees across every page read, which is not the number of pages.
     */
    readonly trees: number;
    /**
     * Page views counted at the door across the pages handed in, added.
     */
    readonly arrivals: number;
    /**
     * Readings of a revision beyond the first, which were dropped.
     */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, which were ignored.
     */
    readonly duplicatedRows: number;
};

type MovementStanding =
/** In at least one of the orders, with a movement and a scale for it. */
"ranked"
/**
 * Compared, scalable, and no stop moved by as much as one reader.
 */
 | "unmoved" | DeploymentChangeSilence;

type PageMovement = {
    /**
     * The pair of siblings it happened at, carried through from the comparison
     * unchanged.
     */
    readonly at: ComparedStop;
    /**
     * How much of the page's readers moved, as a share, with the direction in the
     * name rather than in the sign.
     */
    readonly share: number;
    /**
     * The same movement as readers, at the later window's door scale, or `null`
     * where this page has no scale.
     */
    readonly readers: number | null;
};

type MovedPage = {
    /** The page, which is the earlier reading's tree. */
    readonly treeId: TreeId;
    /** The two revisions compared, which may be the same one read in two windows. */
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience the later window was collected under, or `null` where the
     * reading named none.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: MovementStanding;
    /**
     * Each window's view floor, carried through from its own reading unchanged.
     */
    readonly views: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * Page views counted at the later door, exact, or `null` where that revision
     * has no row.
     */
    readonly opened: number | null;
    /** The later window's own straddle rate, which is what scales the movements. */
    readonly inflation: number | null;
    /**
     * The comparison's own reason for saying nothing, where it gave one.
     */
    readonly silence: ChangeSilence | null;
    /** The stop the change costs most readers at, where it worsened one. */
    readonly worsened: PageMovement | null;
    /** The stop it keeps most readers at, where it improved one. */
    readonly improved: PageMovement | null;
};

type DeploymentChange = {
    /**
     * Every page the change cost readers, worst first.
     */
    readonly harmed: readonly MovedPage[];
    /** Every page it kept readers on, best first, by the same rule. */
    readonly helped: readonly MovedPage[];
    /**
     * Every page in neither order, by tree id and newest later revision first.
     */
    readonly unranked: readonly MovedPage[];
    /** The head of the harm order, which is the page to look at first. `null` where nothing worsened. */
    readonly worst: MovedPage | null;
    /** The head of the help order. `null` where nothing improved. */
    readonly best: MovedPage | null;
    /**
     * How many pages stand in each state, counting a page once however many
     * orders it is in.
     */
    readonly standings: Readonly<Record<MovementStanding, number>>;
    /**
     * Comparisons read, which is pages: one comparison stands per page.
     */
    readonly compared: number;
    /**
     * Page views counted at the later door across the pages read, added once per
     * revision.
     */
    readonly arrivals: number;
    /**
     * Comparisons of a page beyond the first that compared the same two
     * revisions, which were dropped.
     */
    readonly duplicated: number;
    /**
     * Door rows for the later revision beyond the first, which were ignored.
     */
    readonly duplicatedRows: number;
    /**
     * Pages one of whose **forms** was handed in with two different comparisons,
     * of which neither was read.
     */
    readonly ambiguous: readonly TreeId[];
};

type PageDoor = {
    /**
     * `min(appearances, opened)`: the page views a rollup folded, at the door's
     * scale.
     */
    readonly counted: number;
    /**
     * The row's openings, whatever the silence.
     */
    readonly opened: number;
    readonly appearances: number;
    readonly drift: number;
    readonly pending: number;
    /** Set where this page cannot be scaled, in the page's own vocabulary. */
    readonly silence: ReachSilence | null;
};

type ExpiryStop = 
/** The oldest delivery left is inside the kept window, which is the ordinary answer. */
"young"
/** The oldest delivery left is past the window and no fold has counted it. */
 | "uncounted"
/** The scan reached the end of what it read with everything expirable. */
 | "end";

type ExpiryPlan = {
    /** The position to delete below. `null` where nothing may go. */
    readonly before: number | null;
    /** Rows the scan read and left. A floor rather than a total — the scan stops at the first. */
    readonly waiting: number;
    readonly stopped: ExpiryStop;
};

type ExpiryOutcome = {
    readonly outcome: "expired";
    readonly removed: number;
    /**
     * How old the oldest delivery the scan read was, before anything was
     * deleted, in milliseconds at this run's instant.
     */
    readonly oldestMs: number;
    readonly stopped: ExpiryStop;
    /** The scan filled its limit with expirable rows, so another run has work now. */
    readonly more: boolean;
}
/** Nothing in the table may go yet, which is the ordinary answer inside the window. */
 | {
    readonly outcome: "nothing-expired";
    readonly waiting: number;
    /** `null` where the scan read no row at all — a table with nothing in it. */
    readonly oldestMs: number | null;
    readonly stopped: ExpiryStop;
}
/** The window was not usable. Nothing was read or deleted. */
 | {
    readonly outcome: "refused";
    readonly reason: string;
}
/** Read or delete failed. Where it was the delete, the prefix is still there. */
 | {
    readonly outcome: "unavailable";
    readonly error: ReaderSignalStoreError;
};

type ExpiryRequest = {
    readonly keptMs?: number;
    readonly clock?: Clock;
    readonly scanLimit?: number;
};

type ReaderReadings = {
    /** Total time on screen. Summed across batches, because `dwelled` is per-batch. */
    readonly dwellMs: Readonly<Record<NodeId, number>>;
    /** Nodes that came into view at all. `viewed` fires once per node per page view. */
    readonly reached: Readonly<Record<NodeId, true>>;
    /**
     * Times the node itself was used — a link followed, a button pressed, a field
     * filled.
     */
    readonly activations: Readonly<Record<NodeId, number>>;
    readonly opens: Readonly<Record<NodeId, number>>;
    readonly closes: Readonly<Record<NodeId, number>>;
    /**
     * Times a form inside the node was submitted and the browser let it go.
     */
    readonly completions: Readonly<Record<NodeId, number>>;
    /**
     * Times a reader used something *inside* the node — pressed, followed, filled,
     * opened or closed, at any depth.
     */
    readonly engagements: Readonly<Record<NodeId, number>>;
    /**
     * What each node is, as its signals reported it. Kept because a consumer
     * holding only readings would otherwise have to go back to the tree to render
     * a row, and the signals already say.
     */
    readonly types: Readonly<Record<NodeId, PrimitiveType>>;
    readonly batches: number;
    readonly signals: number;
};

type NodeReading = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly dwellMs: number;
    readonly reached: boolean;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /** Times a form inside it was submitted and the browser let it go. */
    readonly completions: number;
    /** Times a reader used something inside it, at any depth. */
    readonly engagements: number;
};

type FormActionSide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, carried through unchanged.
     */
    readonly views: number;
    /** Element nodes this form has, which two forms of one page need not share. */
    readonly parts: number;
    /** Parts with no element parts under them, whose share is withheld structurally. */
    readonly leaves: number;
    /** Whether this side holds uses and credits them to nobody. */
    readonly unwalked: boolean;
};

type PartActionOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this part is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    readonly side: PartAction;
};

type ComparedFormAction = {
    readonly nodeId: NodeId;
    /** The type {@link FormActionComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    readonly one: PartAction;
    readonly other: PartAction;
    /**
     * The form whose readers acted inside it more often, or `null` where no claim
     * stands.
     */
    readonly favours: AudienceId | null;
    /**
     * The distance between the two shares, which is never signed.
     */
    readonly gap: number | null;
};

type FormActionsCounted = {
    /** Parts {@link FormActionComparison.one}'s readers acted inside more often. */
    readonly one: number;
    /** Parts {@link FormActionComparison.other}'s readers acted inside more often. */
    readonly other: number;
    /** Parts the two forms acted inside alike. */
    readonly alike: number;
    /** Parts where one side or the other cannot say. */
    readonly unknown: number;
};

type FormActionComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormActionSide;
    readonly other: FormActionSide;
    /** The two readings this comparison was taken from, so nothing downstream derives them twice. */
    readonly readings: {
        readonly one: PageAction;
        readonly other: PageAction;
    };
    /** Parts both forms have, in the reading order of {@link FormActionComparison.one}. */
    readonly compared: readonly ComparedFormAction[];
    /** Parts exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PartActionOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     */
    readonly disagreed: readonly NodeId[];
    /**
     * Shared nodes one form gives an inside and the other does not.
     */
    readonly insideDisagreed: readonly NodeId[];
    readonly counted: FormActionsCounted;
    /**
     * The root, held against itself across the two forms.
     */
    readonly whole: ComparedFormAction | null;
    /**
     * The shared part with the widest gap, by node id where two tie.
     */
    readonly sharpest: ComparedFormAction | null;
    readonly silence: FormActionSilence | null;
};

type FormCopySide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, which is the denominator of every reach below.
     */
    readonly views: number;
    /**
     * Every word this form says, counted once.
     */
    readonly words: number;
    /** Passages this form has that say something, which two forms need not share. */
    readonly passages: number;
    /** Words this form says in parts its own window can speak for. */
    readonly spoken: number;
};

type PassageOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this passage is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    /** The passage itself, as that form's own window read it. */
    readonly passage: Passage;
    /** What that form's window said about reaching it. */
    readonly side: PassageSide;
};

type ComparedFormPassage = {
    readonly nodeId: NodeId;
    /** The type {@link FormCopyComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The words, the same number on both sides because they are the same words. */
    readonly words: number;
    /** The text itself, so a passage can be quoted back without a second join. */
    readonly text: readonly string[];
    /**
     * Whether either form's part declares no `copy`, so {@link words} is a floor.
     */
    readonly floored: boolean;
    readonly one: PassageSide;
    readonly other: PassageSide;
    /**
     * The form whose readers reached this passage more often, or `null` where no
     * claim stands.
     */
    readonly favours: AudienceId | null;
    /**
     * The words this passage puts in front of one form's average reader over and
     * above the other's: `words × |one.reach − other.reach|`.
     */
    readonly gap: number | null;
};

type RewordedFormPassage = {
    readonly nodeId: NodeId;
    /** The type {@link FormCopyComparison.one} gives it. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The two word counts, which is why there is no single one. */
    readonly words: {
        readonly one: number;
        readonly other: number;
    };
    /** Whether either form declares no `copy`, so its word count is a floor. */
    readonly floored: boolean;
    readonly one: PassageSide;
    readonly other: PassageSide;
    /**
     * The form that says more words here, or `null` where the two say as many
     * words differently.
     */
    readonly wordier: AudienceId | null;
};

type WordsOfForms = {
    /** Words both forms say, word for word, in a node both forms have. */
    readonly shared: number;
    /** Words of passages exactly one form has, by form. */
    readonly only: {
        readonly one: number;
        readonly other: number;
    };
    /**
     * Those words, by what each form's own window said about reaching them. Each
     * form's three add to its own {@link only}.
     */
    readonly onlyByStanding: {
        readonly one: Readonly<Record<PartStanding, number>>;
        readonly other: Readonly<Record<PartStanding, number>>;
    };
    /** Words of passages both forms have and neither says the same way, by form. */
    readonly reworded: {
        readonly one: number;
        readonly other: number;
    };
};

type FormCopyCounted = {
    /** Passages {@link FormCopyComparison.one}'s readers reached more often. */
    readonly one: number;
    /** Passages {@link FormCopyComparison.other}'s readers reached more often. */
    readonly other: number;
    /** Passages the two forms reached alike. */
    readonly alike: number;
    /** Passages where one form or the other cannot say. */
    readonly unknown: number;
};

type SharedWordsRead = {
    /** `Σ(readers × words) ÷ views` for {@link FormCopyComparison.one}. */
    readonly one: number;
    /** The same for {@link FormCopyComparison.other}. */
    readonly other: number;
    /**
     * `|one − other|`, with the direction in {@link favours}.
     */
    readonly gap: number;
    /** The form whose average reader got to more of the shared words. */
    readonly favours: AudienceId | null;
};

type FormCopyComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormCopySide;
    readonly other: FormCopySide;
    /** The two copy readings this comparison was taken from, so nothing downstream derives them twice. */
    readonly readings: {
        readonly one: CopyReading;
        readonly other: CopyReading;
    };
    /** The census of what each form says, with no reader in it. */
    readonly says: WordsOfForms;
    /** Passages both forms say the same way, in the reading order of {@link one}. */
    readonly compared: readonly ComparedFormPassage[];
    /** Passages both forms have and neither says the same way, in the same order. */
    readonly reworded: readonly RewordedFormPassage[];
    /** Passages exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PassageOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     */
    readonly disagreed: readonly NodeId[];
    /** Shared passages by which form's readers reached them more often. */
    readonly counted: FormCopyCounted;
    /**
     * The words those passages say, falling the same way. The four add to
     * {@link WordsOfForms.shared}.
     */
    readonly wordsCounted: FormCopyCounted;
    /** Shared passages whose words are a floor. */
    readonly floored: number;
    /**
     * The shared passages neither form's readers reached, most words first and
     * then in reading order.
     */
    readonly unseenByEither: readonly ComparedFormPassage[];
    /** The shared words each form's average reader got to; `null` where {@link silence} says why not. */
    readonly typical: SharedWordsRead | null;
    /**
     * The shared passage the two forms read most differently, by node id where
     * two tie.
     */
    readonly sharpest: ComparedFormPassage | null;
    readonly silence: FormCopySilence | null;
};

type FormComparisonSilence =
/**
 * The five states in which two readings are not two forms of one page, taken
 * whole from {@link FormPairRefusal}.
 */
FormPairRefusal
/**
 * One of the two windows held no page views.
 */
 | "nothing-measured";

type FormSide = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** `null` where the window named none, or named two with neither asked for. */
    readonly audienceId: AudienceId | null;
    /**
     * That side's page-view floor, which is the denominator of every reach below.
     */
    readonly views: number;
    /** Element nodes this form has, which two forms of one page need not share. */
    readonly parts: number;
};

type FormPartSide = {
    readonly standing: PartStanding;
    /** Distinct page views of this form that reported the part coming into view. */
    readonly readers: number;
    /** That side's own view floor, carried so the share below can be checked. */
    readonly views: number;
    /**
     * {@link FormPartSide.readers} over {@link FormPartSide.views}, or `null`
     * where that window held none.
     */
    readonly reach: number | null;
};

type PartOfForm = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    /** The form this part is in. The other form does not have this node at all. */
    readonly audienceId: AudienceId;
    readonly side: FormPartSide;
};

type ComparedForm = {
    readonly nodeId: NodeId;
    /** The type {@link FormComparison.one} gives it; `disagreed` names the pair if the other differs. */
    readonly type: PrimitiveType;
    readonly role: PrimitiveRole | null;
    readonly one: FormPartSide;
    readonly other: FormPartSide;
    /**
     * The form whose readers reached it more often, or `null` where no claim
     * stands.
     */
    readonly favours: AudienceId | null;
    /**
     * The distance between the two reaches, which is never signed.
     */
    readonly gap: number | null;
};

type FormsCounted = {
    /** Parts {@link FormComparison.one}'s readers reached more often. */
    readonly one: number;
    /** Parts {@link FormComparison.other}'s readers reached more often. */
    readonly other: number;
    /** Parts the two forms reached alike. */
    readonly alike: number;
    /** Parts where one side or the other cannot say. */
    readonly unknown: number;
};

type FormComparison = {
    /** The side whose audience id sorts lower, or the first argument where no pair of names stands. */
    readonly one: FormSide;
    readonly other: FormSide;
    /** Parts both forms have, in the reading order of {@link FormComparison.one}. */
    readonly compared: readonly ComparedForm[];
    /** Parts exactly one form has, by audience and then by node. */
    readonly onlyIn: readonly PartOfForm[];
    /**
     * Shared nodes the two forms give different primitive types.
     */
    readonly disagreed: readonly NodeId[];
    readonly counted: FormsCounted;
    /** The shared part with the widest gap, by node id where two tie; `null` where none can say. */
    readonly sharpest: ComparedForm | null;
    readonly silence: FormComparisonSilence | null;
};

type UnreachedPart = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** Depth in the tree, counting every node; 0 at the root. */
    readonly depth: number;
    /**
     * The part it sits inside, and `null` at the outermost part — which is the
     * one stop that means *the page itself was never reported on*.
     */
    readonly withinId: NodeId | null;
    /**
     * What that containing part's standing was.
     */
    readonly within: PartStanding | null;
    /** Parts in its subtree, itself excluded, whatever each of them reported. */
    readonly beneath: number;
    /**
     * Parts this stop accounts for, itself included — so 1 for a stop with
     * nothing inside it.
     */
    readonly unseen: number;
    /**
     * Parts in its subtree that **did** report reach, which should be none.
     */
    readonly reportedBelow: number;
    /**
     * The words nobody reached here, in reading order: this part's own and those
     * of every part it accounts for.
     */
    readonly words: readonly string[];
};

type PageFrontier = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience the reading was of, carried through from
     * {@link PageReading.audienceId} unchanged.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every audience the window named, carried through from
     * {@link PageReading.audiences} unchanged.
     */
    readonly audiences: readonly AudienceId[];
    /**
     * The floor on page views the reading was drawn from, carried through from
     * {@link PageReading.views}.
     */
    readonly views: number;
    /** Every place the reading stopped, in reading order. */
    readonly frontier: readonly UnreachedPart[];
    /**
     * Parts no view reported reaching — the sum of every stop's `unseen`, and so
     * equal to `skipped` in {@link PageReading.standings}.
     */
    readonly unseen: number;
    /** Parts at least one view reported reaching. */
    readonly read: number;
    /** Parts nothing can be said about. */
    readonly unknown: number;
    /** Every addressed node of the revision, which is the universe the rest is out of. */
    readonly parts: number;
    /**
     * Parts that were reached, hold at least one part, and whose every part went
     * unreached.
     */
    readonly passedOver: readonly NodeId[];
    /**
     * Parts that reported nothing while a part inside them reported reach.
     */
    readonly notReporting: readonly NodeId[];
    /**
     * Rows of the reading that named a node this revision does not contain,
     * carried through from {@link PageReading.orphaned}.
     */
    readonly orphaned: number;
};

type FunnelStage = 
/** Arrivals that never satisfied the pair's first end. */
"before"
/** Arrivals that satisfied the first end and not the second. */
 | "between";

type EndStanding =
/**
 * The revision has an element node with this id, so a count against the end
 * is a fact about readers.
 */
"present"
/**
 * No element node of the revision has this id.
 */
 | "absent";

type PairEnds = {
    readonly from: EndStanding;
    readonly to: EndStanding;
};

type FunnelShare = {
    /**
     * The estimate, against the page views the rollups counted:
     * `count ÷ appearances`.
     */
    readonly share: number | null;
    /**
     * The ceiling, against the page views that began: `count ÷ opened`, never
     * above 1.
     */
    readonly atMost: number | null;
    /**
     * The share applied to the exact count of arrivals — the number a sentence
     * says out loud.
     */
    readonly readers: number | null;
    /**
     * The most readers it could be: the smaller of the count and the openings,
     * which is a whole number of real page views either way. `null` under a
     * silence.
     */
    readonly atMostReaders: number | null;
};

type PairLeak = {
    /**
     * The least it could be: the readers who reached the first end, at the most
     * the true rate could be, on the door's scale.
     */
    readonly atLeast: number;
    /**
     * The most it could be: `reached − converted` on the door's scale, which is
     * the key an order of conversions is on.
     */
    readonly atMost: number;
};

type PairReach = {
    readonly pair: FunnelPair;
    /**
     * Page views that satisfied `from`, exactly as stored: added across rollup
     * windows and therefore generous.
     */
    readonly reached: number;
    /**
     * Page views that satisfied both ends, exactly as stored.
     */
    readonly converted: number;
    /** When the funnel row last moved. */
    readonly updatedAt: string;
    /**
     * Where each end stands against the revision's tree.
     */
    readonly ends: PairEnds;
    /**
     * Either end is {@link EndStanding.absent}, so the question is about a part
     * this revision does not have.
     */
    readonly stale: boolean;
    /**
     * An end the tree does not have, with a count against it: `reached` on an
     * absent `from`, or `converted` on an absent `to`.
     */
    readonly orphaned: boolean;
    /**
     * `converted ÷ reached` — of the readers who got to the first end, the share
     * that finished.
     */
    readonly rate: number | null;
    /**
     * The most the true rate could be, given the straddle §8 measured.
     */
    readonly rateAtMost: number | null;
    /**
     * The readers this pair loses between its two ends, bounded and on the door's
     * scale, or `null` where there is no such loss to put a scale on.
     */
    readonly leak: PairLeak | null;
    /**
     * Of the readers who arrived, the share that got to the first end.
     */
    readonly entry: FunnelShare;
    /** Of the readers who arrived, the share that got to both. Withheld where either end is absent. */
    readonly conversion: FunnelShare;
    /**
     * The share of arrivals that never reached the first end.
     */
    readonly lostBefore: number | null;
    /**
     * The share of arrivals that reached the first end and did not convert.
     */
    readonly lostBetween: number | null;
    /**
     * Which of the two stages cost more readers, by headcount rather than by
     * share, which is the ranking rule for a fall between two siblings at its
     * two-element case.
     */
    readonly worse: FunnelStage | null;
    /**
     * More readers reached the first end than there were page views to reach it
     * in, so no share here can be drawn.
     */
    readonly unreconciled: boolean;
};

type FunnelReach = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience whose answers this reading is of, or `null` where the reading
     * it was taken from named none.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every population the window named, deduplicated and in a stable order.
     */
    readonly audiences: readonly AudienceId[];
    /** Page views that began on this revision. Exact, and addable. */
    readonly opened: number;
    /** The same page views as the rollups counted them: once per window each appeared in. */
    readonly appearances: number;
    /** Appearances in excess of openings — the straddle, measured. Never negative. */
    readonly drift: number;
    /** Openings whose reading no rollup has folded yet. The other sign of the same subtraction. */
    readonly pending: number;
    /** `drift ÷ opened`: how generous every distinct count here is. `null` when nothing opened. */
    readonly inflation: number | null;
    /** When the page-view row last moved, or `null` where there is no row. */
    readonly updatedAt: string | null;
    /** Set where no share can be given, and the reason. `null` where they can. */
    readonly silence: ReachSilence | null;
    /**
     * Nobody's visit spanned two windows, so there is nothing to divide out: the
     * rates are exact and each `rateAtMost` equals its `rate`.
     */
    readonly exact: boolean;
    /**
     * The revision's pairs, ordered by their two ends so a screen does not
     * reorder on a refresh. Deliberately not ranked — see the module note.
     */
    readonly pairs: readonly PairReach[];
    /** Page-view rows for another tree or revision, and ignored. */
    readonly foreign: number;
    /** Page-view rows for this revision beyond the first, where the first stands. */
    readonly duplicated: number;
    /**
     * Funnel rows for another tree or revision, and ignored.
     */
    readonly foreignPairs: number;
    /**
     * Funnel rows for this revision in another audience, and ignored.
     */
    readonly otherAudiencePairs: number;
    /**
     * Funnel rows naming a pair already seen, where every one after the first was
     * ignored.
     */
    readonly duplicatedPairs: number;
    /**
     * Pairs with an end this revision does not have, counted off
     * {@link FunnelReach.pairs} and therefore once each.
     */
    readonly stalePairs: number;
    /** Of those, the ones with a count against the missing end. Counted off the same list. */
    readonly orphanedPairs: number;
};

type FunnelMovement =
/**
 * Readers reached the first end and none of them finished, and now some do —
 * the sentence a change to an ask nobody answers is made for.
 */
"taken-up"
/** Readers finished it and now they reach the first end and do not. */
 | "abandoned"
/**
 * Reached and unfinished before, reached and unfinished now — the asks a
 * change did not fix.
 */
 | "still-unconverted"
/** Readers finished it before and after. */
 | "held"
/**
 * One of the two windows cannot say whether readers finished it.
 */
 | "unknown";

type QuestionMovement =
/** Both ends are in both revisions, so the two sides answer the same question. */
"asked"
/**
 * The earlier revision had both ends and the later one is missing one.
 */
 | "broken"
/** The earlier revision was missing an end and the later one has both: the change put it back. */
 | "restored"
/** An end is missing from both revisions, so neither side was ever answering. */
 | "stale";

type ComparedFunnel = {
    /** The pair as the later window holds it, which is the same question either way. */
    readonly pair: FunnelPair;
    /** The whole of what the earlier window said about it. */
    readonly was: PairReach;
    /** The whole of what the later window said about it. */
    readonly now: PairReach;
    readonly movement: FunnelMovement;
    /** What the change did to whether the question names anything. */
    readonly question: QuestionMovement;
    /**
     * `now.rate ÷ was.rate` — of the readers who got to the first end, how much
     * likelier they are to finish.
     */
    readonly rateRatio: Ratio;
    /**
     * The least the true ratio could be: `now.rate ÷ was.rateAtMost`.
     */
    readonly rateRatioAtLeast: number | null;
    /** The most the true ratio could be: `now.rateAtMost ÷ was.rate`. `null` on the same terms. */
    readonly rateRatioAtMost: number | null;
    /**
     * The bracket clears 1, so the rate moved by more than the straddle alone
     * could account for.
     */
    readonly rateMoved: boolean | null;
    /**
     * `now.entry.share ÷ was.entry.share` — how much likelier an arrival is to
     * get to the first end.
     */
    readonly entryRatio: Ratio;
    /**
     * `now.conversion.share ÷ was.conversion.share` — how much likelier an
     * arrival is to finish, which is the figure a deployment means by *did the
     * change work*.
     */
    readonly conversionRatio: Ratio;
    /**
     * The later window's reach at the earlier window's closing rate, as a share
     * of arrivals: the conversion share if only getting there had moved.
     */
    readonly ifOnlyEntryMoved: number | null;
    /** The other diagonal: the conversion share if only the closing had moved. */
    readonly ifOnlyClosingMoved: number | null;
    /** Which side was enough on its own. `null` where the conversion share did not move. */
    readonly cause: ConversionCause | null;
    /**
     * The movement in the conversion share, put on the later window's scale:
     * `(now.conversion.share − was.conversion.share) × now.opened`.
     */
    readonly readersMoved: number | null;
};

type FunnelChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     */
    readonly audiences: ComparedAudiences;
    /** The two funnel readings this comparison is made of. */
    readonly readings: {
        readonly was: FunnelReach;
        readonly now: FunnelReach;
    };
    /**
     * Every question both windows were asked, ordered by the pair's two ends so a
     * screen does not reorder on a refresh.
     */
    readonly compared: readonly ComparedFunnel[];
    /**
     * Questions only the later window was asked, as it answered them.
     */
    readonly added: readonly PairReach[];
    /** Questions only the earlier window was asked, as it answered them. */
    readonly removed: readonly PairReach[];
    /** Compared pairs by what happened to the verdict. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<FunnelMovement, number>>;
    /** Compared pairs by what the change did to the question. The four add to {@link compared}'s length. */
    readonly questions: Readonly<Record<QuestionMovement, number>>;
    /**
     * The compared pair whose conversion share gained the most readers at the
     * later window's scale, or `null` where none gained.
     */
    readonly mostGained: ComparedFunnel | null;
    /** The compared pair that lost the most, by the same rule. `null` where none lost. */
    readonly mostLost: ComparedFunnel | null;
    /**
     * Compared pairs whose rate ratio is given and whose bracket contains 1, so
     * the straddle alone could account for the whole movement.
     */
    readonly undecided: number;
    /**
     * Neither window had a page view that spanned a rollup boundary, so every
     * rate on both sides is exact and every bracket is a point.
     */
    readonly exact: boolean;
    /**
     * Pairs naming a question already seen on that side, where every one after
     * the first was ignored.
     */
    readonly duplicated: number;
    /** Set where a figure is missing and why. `null` where nothing is. */
    readonly silence: FunnelChangeSilence | null;
};

type CollectionSchedule = {
    /**
     * The instant the reading is taken, as an ISO 8601 timestamp.
     */
    readonly at: string;
    /**
     * The longest a fold may honestly be behind, in milliseconds.
     */
    readonly foldsWithinMs: number;
};

type FaultRemedy =
/** The pages: a newer broadcaster, or one whose delegation walks the ancestry. */
"senders"
/** The deployment's own configuration: the rollup window. */
 | "configuration"
/** The surface that asked: it handed in a tree and a window that do not match, or two reads. */
 | "caller"
/**
 * Nothing the rows can name.
 */
 | "undetermined";

type HealthStanding =
/** Measured, with nothing wrong that these rows can see. */
"sound"
/** At least one fault, named on the row. */
 | "faulted"
/**
 * Nothing was collected about this revision at all.
 */
 | "unmeasured"
/**
 * The door counted page views of this revision and no rollup has folded any of
 * them.
 */
 | "unfolded";

type PageHealth = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: HealthStanding;
    /**
     * Every fault, in the order {@link COLLECTION_FAULTS} publishes them, which is
     * the order they are worth reading in: the one that costs the denominator
     * first, the four that are the deployment's, then the caller's.
     */
    readonly faults: readonly CollectionFault[];
    /**
     * The window's view floor, carried through from the reading unchanged.
     */
    readonly views: number;
    /**
     * Page views counted at the door, exact, or `null` where this revision has no
     * row.
     */
    readonly arrivals: number | null;
    /** The same page views as the rollups saw them, or `null` with no row. */
    readonly appearances: number | null;
    /** This revision's own straddle rate, or `null` where nothing has opened. */
    readonly inflation: number | null;
    /**
     * Openings no rollup has folded yet, which is a figure and never a fault here.
     */
    readonly pending: number;
    /**
     * When a rollup last folded a window holding page views of this revision, or
     * `null` where nothing attests one — including every revision with no door
     * row at all.
     */
    readonly foldedAt: string | null;
    /** Counters naming nodes this revision does not contain. */
    readonly orphaned: number;
    /** Node counters and door rows handed in more than once, added. */
    readonly doubled: number;
    /**
     * Parts that reported nothing while a part inside them reported being
     * reached, which is what `parts-unreporting` is raised on.
     */
    readonly unreporting: number;
};

type CollectionHealth = {
    /** Every revision read, by tree id and newest revision first. */
    readonly pages: readonly PageHealth[];
    /**
     * Faulted revisions the door can price, worst first.
     */
    readonly faulted: readonly PageHealth[];
    /**
     * Faulted revisions with no exact arrival count, by tree id and newest
     * revision first.
     */
    readonly unpriced: readonly PageHealth[];
    /** The faulted page costing the most readers, which is the one to look at first. */
    readonly worst: PageHealth | null;
    readonly standings: Readonly<Record<HealthStanding, number>>;
    /**
     * How many revisions carry each fault.
     */
    readonly faults: Readonly<Record<CollectionFault, number>>;
    /**
     * Page views at the door of every faulted revision the door can price, added
     * — each revision once however many faults it has.
     */
    readonly readersAffected: number;
    /**
     * Page views at the door across every revision read, added.
     */
    readonly arrivals: number;
    /**
     * Openings no rollup has folded, added across the revisions read.
     */
    readonly pending: number;
    /**
     * Revisions with openings waiting and no fold timestamp to judge the wait by.
     */
    readonly unattested: number;
    /**
     * Distinct trees across the revisions read, which is not the number of pages.
     */
    readonly trees: number;
    /**
     * Readings of a revision beyond the first, which were dropped.
     */
    readonly duplicated: number;
};

type IngestOutcome = {
    readonly batches: number;
    readonly signals: number;
    /**
     * Page views this delivery opened, which is what the exact counter moved by.
     */
    readonly opened: number;
    /**
     * Page views counted against a region, which is zero unless the caller said
     * where the delivery came from and the delivery opened a page view.
     */
    readonly regions: number;
    /**
     * Why a counter did not move, when a store refused it.
     */
    readonly openingError?: ReaderSignalStoreError;
    readonly regionError?: ReaderSignalStoreError;
};

type RegionCounter = {
    readonly store: ReaderRegionStore;
    readonly region: ReaderRegion;
};

type DoorCounters = {
    /** When, as an instant every counter this delivery moves is stamped with. The caller's clock. */
    readonly at: string;
    /** Where the delivery came from. Absent on a deployment that does not count regions. */
    readonly region?: RegionCounter;
    /**
     * How many page views began. No switch guards it where it is wired, because a
     * count of page views of a revision names nowhere and nobody — it is the
     * denominator everything else is a rate against.
     */
    readonly openings?: ReaderOpeningCounter;
};

type IngestError = {
    readonly code: "invalid-delivery";
    /** Which batch of the delivery, so a sender with one bad batch can be told which. */
    readonly index: number;
    readonly issues: ReaderSignalParseError["issues"];
} | {
    readonly code: "too-many";
    readonly limit: number;
    readonly given: number;
} | ReaderSignalStoreError;

type InsidePart = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** Depth in the tree, counting every node; 0 at the root. */
    readonly depth: number;
    /**
     * The nearest **addressed** ancestor, which is what `within` names,
     * and `null` at the outermost part.
     */
    readonly withinId: NodeId | null;
    /** What readers did to this part itself, in the range. */
    readonly own: ActedCounts;
    /**
     * What readers did to this part and to every part inside it, in the range.
     */
    readonly inside: ActedCounts;
    /** Addressed nodes in its subtree, itself included — so 1 for a part with no parts in it. */
    readonly parts: number;
    /**
     * The words this part says itself: its declared copy props, and the text
     * handed to it directly or through a slot.
     */
    readonly copy: NodeCopy;
};

type InsideReading = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly range: ArrivalRange;
    /** Every addressed node, in reading order, so a row is always preceded by the row it is inside. */
    readonly parts: readonly InsidePart[];
    /**
     * Everything readers did on this page in the range.
     */
    readonly total: ActedCounts;
    /**
     * Every audience whose rows were summed into this reading.
     */
    readonly audiences: readonly AudienceId[];
    /** Rows summed into the reading. */
    readonly counted: number;
    /**
     * Rows filed under another tree or another revision, and ignored.
     */
    readonly foreign: number;
    /**
     * Rows of this tree and revision whose hour falls outside the range, and
     * ignored.
     */
    readonly outside: number;
    /**
     * Nodes named by a row this revision does not contain.
     */
    readonly orphaned: readonly NodeId[];
    /**
     * The first hour this scope ever counted an action in, carried through from
     * the store.
     */
    readonly begins?: number;
};

type IntakePolicy = {
    /** The largest delivery the door will read, in bytes. */
    readonly maxBytes: number;
    /** Deliveries one subject may make inside a window. */
    readonly deliveries: number;
    readonly windowMs: number;
    /** How many subjects the counter distinguishes before {@link CROWDED_SUBJECT}. */
    readonly subjects: number;
};

type IntakeCount = {
    readonly deliveries: number;
    readonly windowStartedAt: number;
};

type IntakeVerdict = {
    readonly code: "admitted";
    readonly count: IntakeCount;
} | {
    readonly code: "too-large";
    readonly count: IntakeCount;
    readonly limit: number;
    readonly given: number;
} | {
    readonly code: "too-often";
    readonly limit: number;
    readonly retryAfterMs: number;
};

type IntakeGate = {
    /**
     * The policy this gate counts by.
     */
    readonly policy: IntakePolicy;
    readonly admit: (subject: string, bytes: number, now: number) => IntakeVerdict;
    /** How many subjects are being counted. For a status endpoint, not for a decision. */
    readonly subjects: () => number;
};

type RoleDeclarations = {
    readonly typesWithRole: (role: PrimitiveRole) => readonly PrimitiveType[];
};

type ReaderSignalStoreError = {
    readonly code: "unavailable";
    readonly detail: string;
};

type ReceivedBatch = ReaderSignalBatch & {
    readonly seq: number;
    readonly receivedAt: string;
    /**
     * The audience it was **filed** under, which is resolved rather than
     * optional.
     */
    readonly audienceId: AudienceId;
    /**
     * When a fold counted this delivery into the counters, where one has.
     */
    readonly foldedAt?: string;
};

type ReaderSignalReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /**
     * Narrow to rows the fold has counted, or to rows it has not.
     */
    readonly counted?: boolean;
    /**
     * Narrow to the deliveries of **one page view**, named by its key.
     */
    readonly view?: ViewKey;
    /** A cursor from a previous page's `older`/`newer`, passed back unread. */
    readonly cursor?: string;
    /** Default `newer`, which with no cursor is the oldest page — where rollup starts. */
    readonly direction?: PageDirection;
    readonly limit?: number;
};

type ReaderSignalPage = PageEnds & {
    /** Always ascending by `seq`, whichever end the page was taken from. */
    readonly batches: readonly ReceivedBatch[];
};

type ForgetBefore = {
    readonly before: number;
};

type ForgetOutcome = {
    readonly removed: number;
};

type CountedBefore = {
    readonly before: number;
    readonly at: string;
};

type CountedOutcome = {
    /**
     * Rows this call stamped.
     */
    readonly counted: number;
};

interface ReaderSignalJournal {
    readonly receive: (batches: readonly ReaderSignalBatch[]) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly read: (request?: ReaderSignalReadRequest) => Promise<Result<ReaderSignalPage, ReaderSignalStoreError>>;
    /**
     * Record that a fold counted every row below a position.
     */
    readonly counted: (request: CountedBefore) => Promise<Result<CountedOutcome, ReaderSignalStoreError>>;
    readonly forget: (request: ForgetBefore) => Promise<Result<ForgetOutcome, ReaderSignalStoreError>>;
}

type KindSilence =
/**
 * No placement of it has a verdict: every page it stands on held no views, or
 * reported something other than a view of it.
 */
"unread"
/**
 * Nothing in the pages read is of this kind at all.
 */
 | "unplaced";

type KindKey = {
    readonly by: "type";
    readonly type: PrimitiveType;
}
/** `null` is the row for parts whose type declared no role, which is most of a library today. */
 | {
    readonly by: "role";
    readonly role: PrimitiveRole | null;
};

type KindReading = {
    readonly kind: KindKey;
    /** What part a type plays, or `null`. Always `null` on a role row, which carries it as its key. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this kind across the readings. */
    readonly placements: number;
    /** Distinct trees it stands in, which is not the number of placements and not the number of readings. */
    readonly trees: number;
    /** Distinct revisions it stands in: two live revisions of one page are two. */
    readonly revisions: number;
    /** Placements by standing. The three add to {@link placements}. */
    readonly standings: Readonly<Record<PartStanding, number>>;
    /**
     * The share of its placements at least one reader reached. `null` where
     * {@link silence} says why not.
     */
    readonly readShare: number | null;
    /**
     * Why {@link readShare} is not there, and `null` where it is.
     */
    readonly silence: KindSilence | null;
    /**
     * Every word this kind says across its placements, counted once.
     */
    readonly words: number;
    /** Words said by a placement at least one reader reached. */
    readonly wordsReached: number;
    /**
     * {@link wordsReached} over {@link words}; `null` where this kind says nothing
     * at all, which a spacer, a rule and a stack that only holds other parts all
     * do.
     */
    readonly wordShare: number | null;
    /**
     * Placements whose words are a floor, because the type declares no `copy`
     *.
     */
    readonly floored: number;
    /**
     * Time on screen across its placements, added.
     */
    readonly dwellMs: number;
    /** Presses, filed against the part the reader used, so no press is in two rows. */
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /** Forms this kind of part let go. */
    readonly completions: number;
};

type LibraryReading = {
    /**
     * Every type that stands anywhere, most placements skipped first.
     */
    readonly byType: readonly KindReading[];
    /**
     * Every role in the vocabulary that stands anywhere, then the row for parts
     * whose type declared none, in the same order as {@link byType}.
     */
    readonly byRole: readonly KindReading[];
    /** Readings counted, which is revisions of pages and not trees. */
    readonly pages: number;
    /** Distinct trees across them. */
    readonly trees: number;
    /** Element nodes across them, which is the sum of every type row's placements. */
    readonly placements: number;
    /** Placements by standing, over the whole library. */
    readonly standings: Readonly<Record<PartStanding, number>>;
    /**
     * The type skipped in the most places, which is the kind to look at first.
     */
    readonly mostSkipped: KindReading | null;
    /** The type used most, by presses. A count of things that happened, not of readers. */
    readonly mostUsed: KindReading | null;
    /**
     * Readings of a revision beyond the first, which were dropped.
     */
    readonly duplicated: number;
    /**
     * Types whose readings disagreed about the role they play, where the first
     * reading's answer stands.
     */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type KindActionSilence = KindReachSilence
/**
 * No place this kind stands has anything inside it.
 */
 | "unenterable"
/**
 * A page that contributed readers holds actions and credits them to nobody.
 */
 | "unwalked";

type KindAction = {
    readonly kind: KindKey;
    /** What part a type plays, or `null`. Always `null` on a role row, which carries it as its key. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this kind across the readings, as the census counts them. */
    readonly placements: number;
    /**
     * Placements that bear element parts, which are the ones the question exists
     * for.
     */
    readonly insides: number;
    /**
     * Placements with no element part under them, which are in no term here.
     */
    readonly leaves: number;
    /** Placements bearing parts that a window could speak for. */
    readonly verdicts: number;
    /** Placements bearing parts that no row named, and therefore excluded. */
    readonly unknown: number;
    /**
     * Placements with a verdict that no reader reached.
     */
    readonly unmet: number;
    /**
     * Placements at the root of their page.
     */
    readonly roots: number;
    /**
     * Placements by the standing a page's own reading gives them, over
     * **every** placement including the leaves.
     */
    readonly standings: Readonly<Record<ActionStanding, number>>;
    /** Revisions bearing a placement with an inside and a verdict. */
    readonly pages: number;
    /**
     * Of those, the pages that contributed reach — the weights that actually
     * decide the share.
     */
    readonly weighed: number;
    /**
     * Page views that reached an enterable place of this kind, at the door's
     * scale: `reached × min(appearances, opened) ÷ appearances`, added over the
     * bearing placements.
     */
    readonly met: number | null;
    /** The same page views whose reader acted inside the place, at the same scale. */
    readonly acted: number | null;
    /** `met − acted`: the page views that met an enterable place and did nothing in it. */
    readonly ignored: number | null;
    /**
     * `acted ÷ met` — the share of the readers who met it that did something
     * inside it.
     */
    readonly share: number | null;
    /**
     * Whether {@link met} and {@link acted} are on the door's scale, which is the
     * only scale two rows' counts may be compared on.
     */
    readonly onDoorScale: boolean;
    /**
     * Appearances in excess of openings across the weighing pages, added **once
     * per page** rather than once per placement.
     */
    readonly drift: number;
    /**
     * Openings across the weighing pages whose reading no rollup has folded yet.
     */
    readonly pending: number;
    /**
     * No opening is waiting to be folded and nothing is unreconciled, so the
     * weights are final.
     */
    readonly settled: boolean;
    /**
     * Placements crediting more readers with acting inside them than reached them,
     * which no rollup produces.
     */
    readonly unreconciled: number;
    readonly silence: KindActionSilence | null;
};

type LibraryAction = {
    /**
     * Every type that stands anywhere, most readers ignored first.
     */
    readonly byType: readonly KindAction[];
    /** Every role in the vocabulary, then the row for parts whose type declared none, in the same order. */
    readonly byRole: readonly KindAction[];
    /** Readings counted, which is revisions of pages and not trees. */
    readonly pages: number;
    /** Distinct trees across them. */
    readonly trees: number;
    /** Element nodes across them, which is the sum of every type row's placements. */
    readonly placements: number;
    /** Of those, the ones bearing element parts. */
    readonly insides: number;
    /** Of those, the ones with nothing inside them. `placements = insides + leaves`. */
    readonly leaves: number;
    /**
     * Page views counted at the door across the pages read, added **once per
     * page**.
     */
    readonly arrivals: number;
    /** Placements by standing, over the whole library. */
    readonly standings: Readonly<Record<ActionStanding, number>>;
    /**
     * The type the most readers met and did nothing inside, which is the kind to
     * look at first.
     */
