     * scale, by tree, newest revision first, with the side they are on.
     */
    readonly unscaled: readonly UnscaledSide[];
    /**
     * The type that lost the most readers, which is the kind to look at first.
     */
    readonly mostAbandoned: KindReachChange | null;
    /** The type that gained the most readers, by the same rule. */
    readonly mostTakenUp: KindReachChange | null;
    /**
     * Forms read at two revisions in one window, which are in nothing above.
     */
    readonly ambiguous: readonly PageForm[];
    /** Readings of a revision beyond the first, on either side, which were dropped. */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, across the pages of both
     * windows, which were ignored.
     */
    readonly duplicatedRows: number;
    /** Types the two windows disagree about the role of, where the later window's answer stands. */
    readonly roleDisagreed: readonly PrimitiveType[];
};

const weightMovedOver: (weights: readonly {
    readonly was: number;
    readonly now: number;
}[], totals: {
    readonly was: number;
    readonly now: number;
}) => number | null

type ScaledPage = {
    readonly reading: PageReading;
    readonly door: PageDoor;
    readonly duplicatedRows: number;
};

type LibrarySide = {
    readonly pages: PairedWindow;
    /**
     * Each paired page's door, under the same key the pairing uses.
     */
    readonly scaled: ReadonlyMap<string, ScaledPage>;
    readonly duplicatedRows: number;
};

type KindWordReachMovement =
/** The typical reader who met it reaches more of its words now. */
"taken-up"
/** They reach fewer. */
 | "abandoned"
/**
 * They reach exactly as many.
 */
 | "held"
/**
 * No reader reached a word it kept, in either window.
 */
 | "still-unread"
/** {@link KindWordReachChange.silence} says why nothing can be said. */
 | "unknown";

type ReaderWords = {
    /**
     * Passages both revisions say word for word, across the places of this kind
     * that stand in both windows.
     */
    readonly passages: number;
    /** The words those passages say, which is the mass this reading is about. */
    readonly carried: number;
    /**
     * Of {@link passages}, those with a verdict on **both** sides, which is the
     * set every figure below is taken over.
     */
    readonly spoken: number;
    /** The words those passages say: the universe of both masses. */
    readonly comparable: number;
    /** Carried words `unknown` on one side or the other, which are in no mass. */
    readonly unspoken: number;
    /**
     * Comparable passages whose word count is a floor, because the part saying
     * them declares no `copy`.
     */
    readonly floored: number;
    /** The visible words in those passages, which is the part of the mass that is certain. */
    readonly flooredWords: number;
    /**
     * Page views at the door's scale across the pages bearing a comparable word
     * of it, in the earlier window, added **once per page**.
     */
    readonly countedWas: number | null;
    /** The same for the later window. */
    readonly countedNow: number | null;
    /**
     * Reader-words in the earlier window at the door's scale:
     * `Σ readers × words` per page, scaled by `counted ÷ appearances`.
     */
    readonly reachedWas: number | null;
    /** The same for the later window. */
    readonly reachedNow: number | null;
    /**
     * `reachedWas ÷ countedWas` — the carried words the typical reader who met it
     * reached, in the earlier window.
     */
    readonly typicalWas: number | null;
    /** The same in the later window, over the same words. */
    readonly typicalNow: number | null;
    /** `typicalNow − typicalWas`, in words per reader. Withheld under a floor. */
    readonly shift: number | null;
    /**
     * The movement stated at the later window's scale: `shift × countedNow`.
     */
    readonly wordsMoved: number | null;
    /**
     * The later window's per-page rates at the earlier window's weights: the
     * words there would have been if no page's traffic had moved.
     */
    readonly ifTrafficHeld: number | null;
    /**
     * The earlier window's per-page rates at the later window's weights: the
     * words there would have been if no reader had read differently.
     */
    readonly ifReadingHeld: number | null;
    /**
     * How far the weights moved: half the sum of the absolute movements in each
     * page's share of its side's total weight, in `[0, 1]`.
     */
    readonly weightMoved: number | null;
    /** Appearances in excess of openings in the earlier window, over the weighted pages. */
    readonly driftWas: number;
    /** The same for the later window. */
    readonly driftNow: number;
    /** Openings in the earlier window, over the weighted pages, whose reading no rollup has folded. */
    readonly pendingWas: number;
    /** The same for the later window. */
    readonly pendingNow: number;
    /**
     * Comparable passages reporting more readers than their page had appearances,
     * on either side, which no rollup produces.
     */
    readonly unreconciled: number;
    /**
     * Nobody's visit spanned a window on either side, nothing is waiting to be
     * folded, nothing is unreconciled and no word is a floor — so both levels are
     * exact.
     */
    readonly exact: boolean;
};

type KindWordReachChange = {
    readonly kind: KindKey;
    /**
     * What part a type plays, or `null`. Always `null` on a role row,
     * which carries it as its key.
     */
    readonly role: PrimitiveRole | null;
    /** Places of this kind that stand in both windows: the same node of the same page, of this kind on both sides. */
    readonly places: number;
    /** Places of it in the later window with no counterpart in the earlier one. */
    readonly gained: number;
    /** Places of it in the earlier window with no counterpart in the later one. */
    readonly lost: number;
    /**
     * Places of it held still whose text the change rewrote, which are in no mass.
     */
    readonly rewritten: number;
    /**
     * Pages bearing a comparable word of it, which is **forms** and not
     * revisions.
     */
    readonly pages: number;
    readonly words: ReaderWords;
    readonly movement: KindWordReachMovement;
    /** Which side was sufficient, or `null` where the figure did not move or is withheld. */
    readonly cause: ReaderShareCause | null;
    /**
     * Why the figures are not there, and `null` where they are.
     */
    readonly silence: KindWordReachChangeSilence | null;
};

type LibraryWordReachChange = {
    /**
     * Every type that stands in either window, most reader-words lost first.
     */
    readonly byType: readonly KindWordReachChange[];
    /**
     * Every role in the vocabulary, then the row for parts whose type declared
     * none, in the same order as {@link byType}.
     */
    readonly byRole: readonly KindWordReachChange[];
    /**
     * The whole library's carried words, added across every kind exactly once.
     */
    readonly words: ReaderWords;
    /** Forms read in both windows: a page in one of its forms, never a revision. */
    readonly pages: number;
    /** Forms read in the later window only, which is not pages published. */
    readonly pagesGained: number;
    /** Of {@link pagesGained}, forms whose page the earlier window already held. */
    readonly formsGained: number;
    /** Forms read in the earlier window only, which is not pages withdrawn. */
    readonly pagesLost: number;
    /** Of {@link pagesLost}, forms whose page the later window still holds. */
    readonly formsLost: number;
    /** The audiences each window's forms named, published and never refused. */
    readonly audiences: ComparedPopulations;
    /**
     * Paired pages whose revision moved between the windows.
     */
    readonly republished: number;
    /** Places that stand in both windows, of the same type on both sides. */
    readonly placements: number;
    /** Places in the later window only. */
    readonly gained: number;
    /** Places in the earlier window only. */
    readonly lost: number;
    /** Paired nodes whose primitive type changed: a place one kind left and another took. */
    readonly recast: number;
    /** Places held still whose text the change rewrote, across every kind once. */
    readonly rewritten: number;
    /**
     * Page views counted at the door across the paired pages in the earlier
     * window, added once per page.
     */
    readonly arrivalsWas: number;
    /** The same for the later window. */
    readonly arrivalsNow: number;
    /** Paired pages the door could scale in **both** windows, which is where every figure here comes from. */
    readonly scaled: number;
    /**
     * The paired pages bearing a comparable word that the door could not scale,
     * by tree, newest revision first, with the side they are on.
     */
    readonly unscaled: readonly UnscaledSide[];
    /**
     * The type that lost the most reader-words, which is the kind to look at
     * first.
     */
    readonly mostAbandoned: KindWordReachChange | null;
    /** The type that gained the most reader-words, by the same rule. */
    readonly mostTakenUp: KindWordReachChange | null;
    /**
     * Forms read at two revisions in one window, which are in nothing above.
     */
    readonly ambiguous: readonly PageForm[];
    /** Readings of a revision beyond the first, on either side, which were dropped. */
    readonly duplicated: number;
    /**
     * Door rows for one revision beyond the first, across the pages of both
     * windows, which were ignored.
     */
    readonly duplicatedRows: number;
    /** Types the two windows disagree about the role of, where the later window's answer stands. */
    readonly roleDisagreed: readonly PrimitiveType[];
};

type FieldSubject =
/** The part of the page the observation is about. */
"part"
/** Which page, which revision of it, and which form was served. */
 | "page"
/** What was observed about the part — when, how long, open or closed. */
 | "observation"
/**
 * The one visit the delivery belongs to.
 */
 | "page-view"
/** The delivery itself — when it was sent, and what it carried. */
 | "delivery";

type CollectedField = {
    /** The field's name in the delivery, which is what a reader comparing this to a payload sees. */
    readonly field: string;
    /** What it is about. */
    readonly subject: FieldSubject;
    /** One sentence, addressed to the reader. */
    readonly says: string;
};

const SIGNAL_FIELDS: {
    readonly [Kind in ReaderSignalKind]: FieldsOf<Extract<ReaderSignal, {
        kind: Kind;
    }>>;
}

type Refusal =
/**
 * No identifier for a person or a device, and nothing standing in for one.
 */
"no-identifier"
/** No signature derived from a device, a browser or its settings. */
 | "no-fingerprint"
/** Nothing the page said to you and nothing you said to it. */
 | "no-content"
/** No cursor, no scroll trace, no recording. */
 | "no-pointer-path"
/** Nothing that joins one visit to another. */
 | "no-stitching"
/** Nothing derived from your address outlives the request it arrived on. */
 | "no-address";

type RegionNotice = {
    /**
     * The page views a country needs before it is published at all, or `null`
     * where no country is read.
     */
    readonly floor: number | null;
};

type SweepNotice = {
    readonly state: "stated";
    /** The longest the deployment lets pass between sweeps, as it stated it. */
    readonly everyMs: number;
    /**
     * The longest a delivery can live: the later of its two windows, plus one
     * sweep interval.
     */
    readonly goneWithinMs: number;
}
/** Nothing was stated, so nothing here says when a ripe delivery actually goes. */
 | {
    readonly state: "unstated";
};

type CollectionNotice = {
    /** The kinds this configuration broadcasts, in the vocabulary's order. */
    readonly collects: readonly CollectedKind[];
    /** What travels with every delivery. */
    readonly delivery: readonly CollectedField[];
    /** What is never collected, whatever else is configured. */
    readonly refuses: readonly Refusal[];
    /** Where readers are counted from, or that they are not. */
    readonly region: RegionNotice;
    /**
     * How long a delivery waits before it is counted into the totals, in
     * milliseconds.
     */
    readonly bufferMs: number;
    /**
     * How long a delivery itself is kept, measured from when it arrived, in
     * milliseconds.
     */
    readonly keptMs: number;
    /**
     * How often this deployment sweeps, where it has stated it.
     */
    readonly sweep: SweepNotice;
};

type CollectedKind = {
    readonly kind: ReaderSignalKind;
    /** What the page observed, addressed to the reader. */
    readonly observes: string;
    /** Every field that kind carries, including the ones it sometimes omits. */
    readonly carries: readonly CollectedField[];
};

type NoticeRequest = {
    /**
     * The options the page is broadcast with — the same object, so that a notice
     * and the page it is about cannot disagree about which kinds are reported.
     */
    readonly page?: Pick<ReaderSignalOptions, "kinds">;
    /**
     * The window the deployment collects on, from its own `CollectionRequest`
     * (`collect.ts`). The default when absent.
     */
    readonly windowMs?: number;
    /**
     * The region counting this deployment's intake does, where it does any.
     */
    readonly region?: {
        readonly floor?: number;
    };
    /**
     * How often this deployment's sweep runs, where it has stated it.
     */
    readonly sweep?: {
        readonly everyMs: number;
    };
    /**
     * The window this deployment keeps individual deliveries for, from its own
     * `ExpiryRequest` (`expire.ts`). The default when absent.
     */
    readonly keptMs?: number;
};

type PaceStanding =
/**
 * Readers had less than {@link SKIMMED_BELOW} of the time the words take.
 */
"skimmed"
/** Time enough for the words, and not conspicuously more. */
 | "paced"
/** More than {@link LINGERED_ABOVE} times the time the words take. */
 | "lingered"
/** Nothing can be said, and {@link PacedPart.silence} says which nothing. */
 | "unknown";

type PacedPart = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /** null at the root. */
    readonly parentId: NodeId | null;
    /** Distinct page views that reported it coming into view; `0` where no row named it. */
    readonly readers: number;
    /** The words this part says itself, counted. Its own, never its subtree's. */
    readonly words: number;
    /**
     * The words of this part and everything under it.
     */
    readonly wordsWithin: number;
    /**
     * Whether {@link wordsWithin} is a floor rather than a count.
     */
    readonly floored: boolean;
    /** Time on screen, summed across every view in the window. */
    readonly dwellMs: number;
    /**
     * The same time per reader, after {@link PaceOptions.inflation}.
     */
    readonly spentMs: number | null;
    /** What {@link wordsWithin} takes at the costing rate. `0` where it says nothing. */
    readonly needMs: number;
    /**
     * Time spent for every unit of time the words take. `1` is exactly enough.
     */
    readonly pace: number | null;
    readonly standing: PaceStanding;
    /** Why there is no verdict, and `null` where there is one. */
    readonly silence: PaceSilence | null;
    /**
     * Readers times the words they were shown here — the ranking key, and a
     * magnitude rather than a census.
     */
    readonly wordsPassed: number;
};

type PagePace = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** The page's view floor, carried through from the reading unchanged. */
    readonly views: number;
    /** Every element part of the revision, in reading order. */
    readonly parts: readonly PacedPart[];
    readonly standings: Readonly<Record<PaceStanding, number>>;
    /** Why the parts with no verdict have none. Counts only the silent ones. */
    readonly silences: Readonly<Record<PaceSilence, number>>;
    /**
     * The root, judged against the whole page.
     */
    readonly whole: PacedPart | null;
    /**
     * The part of the page most words went unread in: most words passed, then
     * first in reading order.
     */
    readonly mostSkimmed: PacedPart | null;
    /** The inflation that was applied; `0` when none was given. */
    readonly inflation: number;
    /** The costing rate that was applied, which is the default unless one was given. */
    readonly wordsPerMinute: number;
};

type PaceOptions = {
    /**
     * How generous the reader counts are, as `drift ÷ opened` off the page-view
     * rows.
     */
    readonly inflation?: number;
    /**
     * The costing rate, where {@link READING_WORDS_PER_MINUTE} is wrong for this
     * deployment's text.
     */
    readonly wordsPerMinute?: number;
};

type PaceMovement =
/**
 * Skimmed before, and not now — the sentence a rewrite is made for.
 */
"eased"
/** Read before, and skimmed now. */
 | "rushed"
/**
 * Skimmed before and skimmed now — the parts a change did not fix.
 */
 | "still-skimmed"
/** Read on both sides, whether paced or lingered. */
 | "held"
/**
 * One side has no verdict, so there is nothing to compare.
 */
 | "unknown";

type PaceCause =
/**
 * The change alone was enough: the words the later revision asks for would
 * have produced today's verdict at the earlier window's reading time.
 */
"words"
/**
 * The readers alone were enough: the later window's time would have produced
 * today's verdict against the words the page used to say.
 */
 | "time"
/** Either alone would have been enough, so the move is over-determined. */
 | "either"
/** Neither alone would have been enough and the two together were. */
 | "together"
/**
 * A counterfactual has no verdict, so neither question can be answered.
 */
 | "unknown";

type PaceHeld = {
    /** `null` where there is nothing to divide: no reader on the side the time came from, or no words on the side the words came from. */
    readonly pace: number | null;
    /**
     * The verdict that pace carries, under **either** side's floor.
     */
    readonly standing: PaceStanding;
};

type ComparedPace = {
    readonly nodeId: NodeId;
    /** The later revision's type, which is the page somebody is looking at. */
    readonly type: PrimitiveType;
    /** The later revision's role, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** The whole of what the earlier window said about it. */
    readonly was: PacedPart;
    /** The whole of what the later window said about it. */
    readonly now: PacedPart;
    readonly movement: PaceMovement;
    /**
     * `now.pace ÷ was.pace`, with the reason named where there is no quotient
     *.
     */
    readonly paceRatio: Ratio;
    /**
     * `now.spentMs ÷ was.spentMs` — the readers' side of the division.
     */
    readonly timeRatio: Ratio;
    /**
     * `now.needMs ÷ was.needMs` — the page's side of the division.
     */
    readonly needRatio: Ratio;
    /** The later window's time against the earlier revision's words — the readers alone. */
    readonly ifWordsHeld: PaceHeld;
    /** The earlier window's time against the later revision's words — the change alone. */
    readonly ifTimeHeld: PaceHeld;
    /** Which side the verdict moved with, and `null` where it did not move. */
    readonly cause: PaceCause | null;
};

type TimeCount = {
    readonly was: number;
    readonly now: number;
    readonly change: number;
};

type PaceChange = {
    /** The earlier reading's tree. The two agree unless `silence` is `different-trees`. */
    readonly treeId: TreeId;
    readonly revisions: {
        readonly was: number;
        readonly now: number;
    };
    /**
     * The audience each side was of, where its reading named one.
     */
    readonly audiences: ComparedAudiences;
    /** The two pace readings this comparison is made of. */
    readonly readings: {
        readonly was: PagePace;
        readonly now: PagePace;
    };
    /**
     * Every part both revisions have that says something on either side, in the
     * **later** reading order.
     */
    readonly compared: readonly ComparedPace[];
    /**
     * Parts only the later revision has, as it paced them, in its reading order.
     */
    readonly added: readonly PacedPart[];
    /** Parts only the earlier revision had, as it paced them, in its reading order. */
    readonly removed: readonly PacedPart[];
    /** Compared parts by what happened to the verdict. The five add to {@link compared}'s length. */
    readonly movements: Readonly<Record<PaceMovement, number>>;
    /**
     * The parts whose verdict moved, by what moved it. The five add to
     * `movements.eased + movements.rushed`.
     */
    readonly causes: Readonly<Record<PaceCause, number>>;
    /**
     * The root, compared against itself across the two revisions.
     */
    readonly whole: ComparedPace | null;
    /**
     * The part the change made most room to read: `eased`, most words passed
     * now, then first in the later reading order.
     */
    readonly mostEased: ComparedPace | null;
    /** The part it cost most, on the same terms. */
    readonly mostRushed: ComparedPace | null;
    /**
     * The parts readers skimmed before and skim now, most words passed first,
     * then in the later reading order.
     */
    readonly stillSkimmed: readonly ComparedPace[];
    /**
     * What the two revisions ask of a reader who reads every word of them, before
     * and after.
     */
    readonly need: TimeCount | null;
    /** Why there is no comparison of the reading, or `null` where there is one. */
    readonly silence: PaceChangeSilence | null;
    /** The costing rate both sides were read at, which is the published default unless one was given. */
    readonly wordsPerMinute: number;
    /** The straddle correction applied to each side; `0` where none was given. */
    readonly inflation: {
        readonly was: number;
        readonly now: number;
    };
};

type PaceChangeOptions = {
    readonly inflation?: {
        readonly was?: number;
        readonly now?: number;
    };
    readonly wordsPerMinute?: number;
};

type RevisionViews = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly views: number;
};

type ReaderPageViews = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * Page views that *began* on this revision.
     */
    readonly opened: number;
    /**
     * The same page views as the rollups saw them: once per window each appeared
     * in.
     */
    readonly appearances: number;
};

type StoredPageViews = ReaderPageViews & {
    /** The audience these page views were served under. See `StoredTally.audienceId`. */
    readonly audienceId: AudienceId;
    /**
     * When either writer last moved this row.
     */
    readonly updatedAt: string;
    /**
     * When a rollup last folded a window holding page views of this revision, or
     * absent where nothing attests a fold.
     */
    readonly foldedAt?: string;
};

type RevisionPageViews = ReaderPageViews & {
    /**
     * The audience this reading is of, or `null` where it is of every form the
     * window held.
     */
    readonly audienceId: AudienceId | null;
    /**
     * The audiences whose rows were added into this reading, deduplicated and in
     * a stable order.
     */
    readonly audiences: readonly AudienceId[];
    /**
     * When either writer last moved a row behind this reading — the newest of
     * them where it is a sum, because the question is when the number last
     * changed and the busiest form is what last changed it.
     */
    readonly updatedAt: string;
    /**
     * The fold this reading is waiting on: the oldest fold attested by a row that
     * still has openings pending, or the oldest attested of them all where none
     * has, and absent where nothing attests one.
     */
    readonly foldedAt?: string;
    /**
     * Appearances in excess of openings — the over-count in every distinct view
     * count stored against this revision, measured rather than bounded.
     */
    readonly drift: number;
    /**
     * Page views that began and whose batches no rollup has folded yet — the
     * buffer, as a number.
     */
    readonly pending: number;
    /**
     * `drift ÷ opened`: how generous the distinct counts against this revision
     * are, as a fraction. `null` when nothing has opened, because the question
     * has no answer rather than the answer nought.
     */
    readonly inflation: number | null;
};

type PageViewReading = {
    /** Page views that began, across every row read. Exact, and addable. */
    readonly opened: number;
    readonly appearances: number;
    readonly drift: number;
    readonly pending: number;
    readonly inflation: number | null;
    /** Newest revision first, trees in id order, so a screen does not reorder on a refresh. */
    readonly revisions: readonly RevisionPageViews[];
};

type PageViewsFor = {
    /**
     * This revision's door, read through {@link pageViewReadingOf}, or `null`
     * where this revision has none.
     */
    readonly measured: RevisionPageViews | null;
    /**
     * Rows for another tree or another revision, and ignored.
     */
    readonly foreign: number;
    /**
     * Rows for this tree and revision, in another audience, and ignored.
     */
    readonly otherAudience: number;
    /**
     * Rows for this tree, revision **and audience** beyond the first of that
     * audience, where every one after it was ignored.
     */
    readonly duplicated: number;
};

type RevisionOf = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly audienceId?: AudienceId | null;
};

type PartStanding =
/** At least one view reported it coming into view. */
"read"
/**
 * The window held views of this revision, and none of them said anything
 * about this part at all.
 */
 | "skipped"
/**
 * Nothing can be said.
 */
 | "unknown";

type PartReading = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root. */
    readonly depth: number;
    /**
     * The **tree** parent, which may be a node that is in no part's list, and
     * `null` at the root.
     */
    readonly parentId: NodeId | null;
    /**
     * The nearest **addressed** ancestor — the part this part sits inside — and
     * `null` at the outermost part.
     */
    readonly withinId: NodeId | null;
    readonly standing: PartStanding;
    /**
     * The counters, or `undefined` where no signal in the window named it.
     */
    readonly counters: ReaderTally | undefined;
    /**
     * The words this part says itself: its declared copy props, and the text
     * handed to it directly or through a slot.
     */
    readonly copy: NodeCopy;
};

type RoleReading = {
    /** `null` is the row for parts whose type declared no role, which is most of a page today. */
    readonly role: PrimitiveRole | null;
    /** Element nodes of this revision playing it. */
    readonly parts: number;
    readonly standings: Readonly<Record<PartStanding, number>>;
    readonly dwellMs: number;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    readonly completions: number;
};

type PageReading = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience whose counters this reading is of, or `null` where nothing
     * said.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every audience the window named, whether or not it was the one read.
     */
    readonly audiences: readonly AudienceId[];
    /**
     * Counters filed under this tree and revision, in an audience other than the
     * one read, and ignored.
     */
    readonly otherAudience: number;
    /**
     * A floor on the page views the window held, not a count of them.
     */
    readonly views: number;
    /** Every element node, in reading order. */
    readonly parts: readonly PartReading[];
    /** Every role in the vocabulary, then the row for parts that declared none. */
    readonly roles: readonly RoleReading[];
    readonly standings: Readonly<Record<PartStanding, number>>;
    /**
     * Counters handed in that are filed under another tree or another revision,
     * and were ignored.
     */
    readonly foreign: number;
    /**
     * Counters filed under this tree and revision, naming a node this tree does
     * not contain.
     */
    readonly orphaned: readonly NodeId[];
    /**
     * Nodes handed in more than once, where every row but the first was ignored.
     */
    readonly duplicated: readonly NodeId[];
};

type ReadingStep = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    readonly standing: PartStanding;
    /**
     * Distinct page views that reported it coming into view, and `0` where no row
     * named it at all.
     */
    readonly reached: number;
    /**
     * Whether this step can be either end of a stop.
     */
    readonly anchors: boolean;
};

type ReadingStop = {
    /** The part they reached. */
    readonly after: NodeId;
    /** The next part in the run that could anchor a stop, which fewer reached. */
    readonly before: NodeId;
    /** Views that reached `after`, which is the denominator of `share`. */
    readonly reached: number;
    /** Views that reached `after` and not `before`. */
    readonly lost: number;
    /**
     * `lost ÷ reached`, in `(0, 1]`.
     */
    readonly share: number;
};

type ReadingRun = {
    readonly parentId: NodeId;
    /** The depth of the steps, which is one below the parent's. */
    readonly depth: number;
    readonly steps: readonly ReadingStep[];
    /** Every fall, in run order. */
    readonly stops: readonly ReadingStop[];
    /**
     * The last step in run order that any view reached, or `null` where none did.
     */
    readonly furthest: NodeId | null;
    /**
     * Pairs where more views reached the later part than the earlier one.
     */
    readonly gained: number;
};

type ReadingProgress = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience the reading was of, carried through unchanged.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every audience the window named, carried through unchanged.
     */
    readonly audiences: readonly AudienceId[];
    /**
     * The page's view floor, carried through from the reading unchanged.
     */
    readonly views: number;
    /**
     * Every run of two or more children, in reading order.
     */
    readonly runs: readonly ReadingRun[];
    /**
     * The sharpest fall on the page: most views lost, then largest share, then
     * first in reading order.
     */
    readonly steepest: ReadingStop | null;
    /**
     * Parts that could not anchor a stop, because they reported something other
     * than coming into view.
     */
    readonly unanchored: readonly NodeId[];
    /** Every run's {@link ReadingRun.gained}, added. */
    readonly gained: number;
};

type RatioAbsence =
/**
 * One of the two windows did not measure this, so there is nothing to divide.
 */
"unmeasured"
/**
 * Both windows measured it and the earlier one measured nought.
 */
 | "from-nothing";

type Ratio = {
    /** `now ÷ was`, or `null` where {@link absent} says why there is none. */
    readonly ratio: number | null;
    /** Why there is no quotient, or `null` where there is one. */
    readonly absent: RatioAbsence | null;
};

type ReachSilence =
/**
 * No page-view row for this tree and revision.
 */
"unmeasured"
/**
 * The row is there and nothing in it says a page view ever began.
 */
 | "unopened"
/**
 * Readers arrived and no rollup has folded a window yet.
 */
 | "uncounted";

type PartReach = {
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** What part it plays, or `null` where its type declared none. */
    readonly role: PrimitiveRole | null;
    /** 0 at the root, as the reading's outline gives it. */
    readonly depth: number;
    readonly standing: PartStanding;
    /**
     * Distinct page views that saw it, exactly as stored: added across rollup
     * windows and therefore generous.
     */
    readonly reached: number;
    /**
     * The share of page views that got this far, as the rollups counted both
     * ends: `reached ÷ appearances`.
     */
    readonly share: number | null;
    /**
     * The most the share could be: `reached ÷ opened`, never above 1.
     */
    readonly atMost: number | null;
    /**
     * The share applied to the exact count of readers who arrived — the number a
     * sentence can say out loud.
     */
    readonly readers: number | null;
    /**
     * The most readers who could have got here: the smaller of `reached` and the
     * openings, which is a whole number of real page views either way.
     */
    readonly atMostReaders: number | null;
    /**
     * More reach than there were page views to be reached in, so the share sits
     * above 1 and no figure here can be drawn.
     */
    readonly unreconciled: boolean;
};

type PageReach = {
    readonly treeId: TreeId;
    readonly revision: number;
    /** Page views that began on this revision. Exact, and addable. */
    readonly opened: number;
    /** The same page views as the rollups counted them: once per window each appeared in. */
    readonly appearances: number;
    /** Appearances in excess of openings — the straddle, measured. Never negative. */
    readonly drift: number;
    /** Openings whose reading no rollup has folded yet. The other sign of the same subtraction. */
    readonly pending: number;
    /** `drift ÷ opened`: how generous every distinct count here is. `null` when nothing opened. */
    readonly inflation: number | null;
    /** When the page-view row last moved, or `null` where there is no row. */
    readonly updatedAt: string | null;
    /**
     * The floor the counters give on their own: the largest `views` any one row
     * reports.
     */
    readonly countedViews: number;
    /**
     * Set where no share can be given, and the reason. `null` where they can.
     */
    readonly silence: ReachSilence | null;
    /**
     * Nobody's visit spanned two windows, so there is nothing to divide out: the
     * estimate and the ceiling are the same number and the shares are exact.
     */
    readonly exact: boolean;
    /** Every part of the revision, in reading order, as the reading had them. */
    readonly parts: readonly PartReach[];
    /**
     * The parts whose reach could not be reconciled with the openings.
     */
    readonly unreconciled: readonly NodeId[];
    /**
     * Page-view rows handed in for another tree or another revision, and ignored.
     */
    readonly foreign: number;
    /**
     * Rows for this tree and revision beyond the first, where every one after it
     * was ignored.
     */
    readonly duplicated: number;
};

type RegionMovement =
/** Named in both windows, and more views in the later one. */
"grew"
/** Named in both windows, and fewer views in the later one. */
 | "shrank"
/** Named in both windows, and exactly as many views. */
 | "steady"
/**
 * Unnamed in the earlier window and named in the later one.
 */
 | "thickened"
/**
 * Named in the earlier window and unnamed in the later one.
 */
 | "thinned";

type RegionSide = {
    /** Page views that began here, or `undefined` where the floor withheld the bucket. */
    readonly views: number | undefined;
    /**
     * {@link views} over every view in that window, named and withheld, or
     * `undefined` with it.
     */
    readonly share: number | undefined;
};

type ComparedRegion = {
    readonly region: ReaderRegion;
    readonly was: RegionSide;
    readonly now: RegionSide;
    readonly movement: RegionMovement;
    /**
     * `now.share − was.share`, or `undefined` where either window withheld the
     * bucket.
     */
    readonly shift: number | undefined;
    /**
     * `now.views − was.views`, or `undefined` where either window withheld the
     * bucket.
     */
    readonly change: number | undefined;
};

type UnaccountedShares = {
    readonly was: number;
    readonly now: number;
};

type Arrivals = {
    readonly was: number;
    readonly now: number;
};

type ReadershipChange = {
    /**
     * The floor both maps were read at, or `undefined` where they differ and
     * nothing was compared.
     */
    readonly floor: number | undefined;
    readonly comparability: ReadershipComparability;
    /**
     * The audience each map was of, where it named one.
     */
    readonly audiences: ComparedAudiences;
    /**
     * The audiences each map's rows named, which is what each side was a sum
     * over.
     */
    readonly populations: ComparedPopulations;
    /**
     * Half the sum of the absolute share movements over the regions both maps
     * name, in `[0, 1]`, or `undefined` where nothing was compared.
     */
    readonly moved: number | undefined;
    /**
     * {@link moved} plus the whole unaccounted share of both windows, capped at
     * 1, or `undefined` with it.
     */
    readonly movedAtMost: number | undefined;
    /**
     * Every region either map names, most-moved first.
     */
    readonly regions: readonly ComparedRegion[];
    /**
     * The region carrying the largest absolute {@link ComparedRegion.shift}, or
     * `undefined` where no region is named in both maps.
     */
    readonly loudest: ReaderRegion | undefined;
    /**
     * The share of each window's views that is in no comparable row: its withheld
     * buckets, and the buckets the other window withheld.
     */
    readonly unaccounted: UnaccountedShares;
    /**
     * Page views that began in each window, named and withheld.
     */
    readonly arrivals: Arrivals;
};

type ReaderRegionCount = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly region: ReaderRegion;
    /** Page views that *began* here, so a longer visit is not a bigger number. */
    readonly views: number;
};

type StoredRegionCount = ReaderRegionCount & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

interface ReaderRegionStore {
    /**
     * Add views to the buckets they belong in, creating rows that do not exist
     * yet. Additive for the same reason applying a rollup is: every call reports
     * what just arrived rather than what is true so far.
     */
    readonly count: (counts: readonly ReaderRegionCount[], at: string,
    /** The audience the delivery was served under. Omitted is `aud_everyone`. */
    audience?: AudienceId) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly regions: (request?: TallyReadRequest) => Promise<Result<readonly StoredRegionCount[], ReaderSignalStoreError>>;
}

type RegionBucket = {
    readonly region: ReaderRegion;
    readonly views: number;
};

type RegionReading = {
    /** The floor the rows were read at, so a screen can say what it is withholding by. */
    readonly floor: number;
    /**
     * The audience whose arrivals this map is of, or `null` where nothing said.
     */
    readonly audienceId: AudienceId | null;
    /**
     * Every audience the rows this map summed named, deduplicated and in a stable
     * order.
     */
    readonly audiences: readonly AudienceId[];
    /** Buckets large enough to name, most-read first. */
    readonly regions: readonly RegionBucket[];
    /** What was too small to name, as a total that names nowhere. */
    readonly withheld: {
        readonly buckets: number;
        readonly views: number;
    };
    /** Every view in the rows, named or withheld. A reading never loses one. */
    readonly views: number;
};

type RegionReadingOptions = {
    /** Raised above {@link DEFAULT_REGION_FLOOR}; a smaller number is the default.  */
    readonly floor?: number;
};

type RegionReadingFor = {
    /** The revision's own map, floored. */
    readonly reading: RegionReading;
    /**
     * Rows for another tree or another revision, and ignored.
     */
    readonly foreign: number;
    /**
     * Rows for this revision in another audience, and ignored.
     */
    readonly otherAudience: number;
    /**
     * Rows naming a region **and an audience** this revision already had a row
     * for, beyond the first, every one of which was ignored.
     */
    readonly duplicated: number;
};

type RegionPageStanding =
/** Every view in the bucket is on a page the breakdown names. */
"attributed"
/** Some of the bucket's views are on named pages and the rest are withheld. */
 | "partly-attributed"
/**
 * No page in this place cleared the floor, so the bucket's views are named
 * and nothing in it is attributed.
 */
 | "unattributable";

type RegionPage = {
    readonly treeId: TreeId;
    /**
     * Page views that began here, summed over the revisions and the forms the
     * rows named.
     */
    readonly views: number;
    /**
     * This page's share of **the whole bucket**, including the views the
     * breakdown withheld.
     */
    readonly share: number | undefined;
};

type RegionPageBreakdown = {
    readonly region: ReaderRegion;
    /** The bucket's own total, which is the map's number unchanged. */
    readonly views: number;
    /** Pages with enough readers in this place to name, most-read first. */
    readonly pages: readonly RegionPage[];
    /** What was too small to name here, as a total that names no page. */
    readonly withheld: {
        readonly pages: number;
        readonly views: number;
    };
    readonly standing: RegionPageStanding;
};

type RegionPagesOptions = {
    /**
     * The floor under a named cell, which is the deployment's and is required.
     */
    readonly floor: number;
};

type RegionPagesReading = {
    /** The map itself, unchanged, so a breakdown's totals cannot disagree with it. */
    readonly map: RegionReading;
    /**
     * One breakdown per named bucket, in the map's order, so a surface drawing
     * both reads them side by side.
     */
    readonly regions: readonly RegionPageBreakdown[];
};

type RetentionPromise =
/**
 * The deployment stated no sweep interval, so its notice publishes no
 * ceiling.
 */
{
    readonly state: "unpromised";
}
/**
 * The run read no delivery, so nothing here says how old the oldest one is.
 */
 | {
    readonly state: "unread";
}
/**
 * Nothing in the table is old enough to delete, so nothing in it can be past
 * the ceiling.
 */
 | {
    readonly state: "unripe";
}
/**
 * The oldest delivery in the buffer is within the ceiling the notice
 * publishes.
 */
 | {
    readonly state: "kept";
    /** How old the oldest delivery still in the table was, in milliseconds. */
    readonly oldestMs: number;
    /** The ceiling the notice publishes: the later of the two windows plus one sweep. */
    readonly goneWithinMs: number;
}
/**
 * A delivery is older than the ceiling the notice publishes, so that sentence
 * is false and was false for `byMs` before this run.
 */
 | {
    readonly state: "broken";
    readonly oldestMs: number;
    readonly goneWithinMs: number;
    /** How far past the ceiling the oldest delivery is. */
    readonly byMs: number;
    /**
     * Whether what is holding the oldest delivery is that no fold has counted
     * it (`expire.ts`).
     */
    readonly uncounted: boolean;
};

type ReaderTally = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly nodeId: NodeId;
    readonly type: PrimitiveType;
    /** Distinct page views that produced any signal at all about this node. */
    readonly views: number;
    /** Distinct page views in which it came into view. The denominator of a funnel. */
    readonly reached: number;
    /**
     * Distinct page views in which a reader used something *inside* this node —
     * pressed a link or button, filled a field, opened or closed a disclosure.
     */
    readonly engaged: number;
    readonly dwellMs: number;
    readonly activations: number;
    readonly opens: number;
    readonly closes: number;
    /**
     * Times a form inside this node was submitted and the browser let it go.
     */
    readonly completions: number;
};

type FunnelEnd = {
    readonly nodeId: NodeId;
    readonly kind: ReaderSignalKind;
};

type FunnelPair = {
    readonly from: FunnelEnd;
    readonly to: FunnelEnd;
};

type FunnelAnswer = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly pair: FunnelPair;
    /** Views that satisfied `from`. */
    readonly reached: number;
    /** Views that satisfied both. Never greater than `reached`. */
    readonly converted: number;
};

type Rollup = {
    readonly tallies: readonly ReaderTally[];
    readonly funnels: readonly FunnelAnswer[];
    /** Distinct page views seen, across every tree and revision in the input. */
    readonly views: number;
    /**
     * The same page views, per tree and revision — one appearance each, in this
     * window.
     */
    readonly appearances: readonly RevisionViews[];
    /**
     * Batches that carried no view key.
     */
    readonly uncorrelated: number;
    /**
     * Batches this fold refused as a repeat of one it had already folded.
     */
    readonly redelivered: number;
    /**
     * The same occurrences as the tallies' three delegated kinds, filed under the
     * hour the door received them in (`acted.ts`).
     */
    readonly acted: readonly ActedHourCount[];
    /**
     * Batches that carried no instant the door received them at, so their
     * occurrences are in the tallies and in no hour.
     */
    readonly undated: number;
};

type RollupOptions = {
    /**
     * The funnels this deployment asked for. Absent means none: a pair is a
     * question somebody wrote down, and a rollup does not invent questions.
     */
    readonly pairs?: readonly FunnelPair[];
};

type DatedBatch = ReaderSignalBatch & {
    readonly receivedAt?: string;
};

type ReaderSignalParseError = {
    readonly code: "invalid-batch";
    readonly issues: readonly {
        readonly path: string;
        readonly message: string;
    }[];
};

type ReadingSilence = {
    /**
     * What the reading reported, as the matching `meaningOf…Silence` gives it, or
     * `null` where it answered.
     */
    readonly meaning: SilenceMeaning | null;
    /**
     * The page in the form this reading was of, or absent where the reading is of
     * no one page.
     */
    readonly form?: PageForm | null;
};

type SilenceStanding = {
    readonly condition: SilenceCondition;
    readonly subject: SilenceSubject;
    /**
     * The vocabulary of the **first** reading that reported it, kept so that a
     * surface can still print that reading's own sentence.
     */
    readonly vocabulary: SilenceVocabulary;
    /** Every vocabulary that reported it, each once, in the order they arrived. */
    readonly vocabularies: readonly SilenceVocabulary[];
    /** How many readings reported it. */
    readonly readings: number;
    /** The pages it cost, each once however many of their readings reported it. */
    readonly forms: readonly PageForm[];
    /** How many of the readings that reported it were of no one page. */
    readonly wide: number;
};

type SilenceGroup = {
    /** Every reading handed over in this group, silent or not. */
    readonly readings: number;
    /** How many of them were silent. */
    readonly silent: number;
    /**
     * The distinct states they are in, in the order they arrived, each keeping the
     * first reading's vocabulary.
     */
    readonly states: readonly SilenceMeaning[];
};

type FormSilences = SilenceGroup & {
    readonly form: PageForm;
};

type SilenceCensus = {
    /**
     * Every reading handed over, silent or not, which is the denominator the
     * caller chose by choosing what to hand in.
     */
    readonly readings: number;
    /** How many of them were silent. `readings = silent + answered`. */
    readonly silent: number;
    readonly answered: number;
    /**
     * The distinct states, in the order the readings were handed over.
     */
    readonly states: readonly SilenceStanding[];
    /** The same readings by page, in form order rather than arrival order. */
    readonly byForm: readonly FormSilences[];
    /** The readings of no one page, which no form row holds. */
    readonly wide: SilenceGroup;
};

type SilenceSubject =
/** One revision of one page, and the window of counters read against it. */
"page"
/** One part of one revision. */
 | "part"
/**
 * The two readings held against each other, naming neither side.
 */
 | "comparison"
/**
 * One kind of part, everywhere it stands in the pages read.
 */
 | "kind";

type SilenceMeaning = {
    readonly condition: SilenceCondition;
    readonly subject: SilenceSubject;
    /** The reading that published it, kept so that its own sentence can still be printed. */
    readonly vocabulary: SilenceVocabulary;
};

type SilenceRelation =
/**
 * One condition about one subject: the two readings are silent for the same
 * reason about the same thing, and one sentence serves both.
 */
"one-state"
/**
 * One condition about two subjects.
 */
 | "one-reason"
/** Two conditions, which a surface has to print separately or choose between. */
 | "unrelated";

type StoredTally = ReaderTally & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

type StoredFunnel = FunnelAnswer & {
    readonly audienceId: AudienceId;
    readonly updatedAt: string;
};

type TallyReadRequest = {
    /** Absent reads every tree the handle can see, which is the scope rule. */
    readonly treeId?: TreeId;
    /**
     * Absent reads every audience.
     */
    readonly audience?: AudienceId;
    /**
     * Absent reads every revision.
     */
    readonly revision?: number;
};

interface ReaderOpeningCounter {
    /**
     * Add the page views a delivery opened, creating rows that do not exist yet.
     */
    readonly opened: (openings: readonly RevisionViews[], at: string,
    /**
     * The audience the delivery was served under. Omitted is
     * `aud_everyone`, so a door that serves one form of every page calls this
     * exactly as it did.
     */
    audience?: AudienceId) => Promise<Result<void, ReaderSignalStoreError>>;
}

type AppliedCounters = {
    readonly tallies: readonly ReaderTally[];
    readonly funnels: readonly FunnelAnswer[];
    /**
     * The window's page views, per revision, for the counter the exact count
     * is compared against.
     */
    readonly appearances?: readonly RevisionViews[];
    /**
     * The same window's occurrences of the three delegated kinds, filed under the
     * hour the door received them in (`acted.ts`).
     */
    readonly acted?: readonly ActedHourCount[];
};

type AudienceCounters = AppliedCounters & {
    /** The audience this fold was taken over. Omitted is `aud_everyone`. */
    readonly audience?: AudienceId;
};

interface ReaderTallyStore extends ReaderOpeningCounter {
    /**
     * Add a whole window's counters to what is already there, every audience in
     * it, in one atomic write — creating rows that do not exist yet.
     */
    readonly applyWindow: (window: readonly AudienceCounters[], at: string) => Promise<Result<void, ReaderSignalStoreError>>;
    /**
     * One audience's counters, which is {@link applyWindow} over a single entry
     * and is implemented as exactly that in both shipped stores — so the two
     * cannot drift on the half that matters.
     */
    readonly apply: (counters: AppliedCounters, at: string,
    /**
     * The audience whose counters these are. Omitted is `aud_everyone`.
     */
    audience?: AudienceId) => Promise<Result<void, ReaderSignalStoreError>>;
    readonly tallies: (request?: TallyReadRequest) => Promise<Result<readonly StoredTally[], ReaderSignalStoreError>>;
    readonly funnels: (request?: TallyReadRequest) => Promise<Result<readonly StoredFunnel[], ReaderSignalStoreError>>;
    /**
     * How many page views there were, which is the denominator every rate on a
     * screen needs and the only row here written from two sides.
     */
    readonly pageViews: (request?: TallyReadRequest) => Promise<Result<readonly StoredPageViews[], ReaderSignalStoreError>>;
    /**
     * The same page views, by the hour they began in, over a range (`arrivals.ts`).
     */
    readonly arrivals: (request?: ArrivalReadRequest) => Promise<Result<StoredArrivals, ReaderSignalStoreError>>;
    /**
     * What readers did, per part, by the hour they did it in, over a range
     * (`acted.ts`).
     */
    readonly acted: (request?: ActedReadRequest) => Promise<Result<StoredActed, ReaderSignalStoreError>>;
}

type ArrivalReadRequest = TallyReadRequest & {
    /** Inclusive. Absent reads from the first hour the scope has. */
    readonly from?: number;
    /** Exclusive. Absent reads to the last hour the scope has. */
    readonly to?: number;
};

type ActedReadRequest = ArrivalReadRequest & {
    readonly nodeId?: NodeId;
};

type PageUnread = {
    readonly treeId: TreeId;
    readonly revision: number;
    /**
     * The audience this row is about, or `null` where the reading named none.
     */
    readonly audienceId: AudienceId | null;
    readonly standing: UnreadStanding;
    /** The page's frontier reading, carried whole and unchanged. */
    readonly reading: PageFrontier;
    /**
     * The place one fix recovers the most of this page at, or `null` where the
     * order did not rank it.
     */
    readonly at: UnreachedPart | null;
    /**
     * Parts of the page that one place accounts for, which is the key the order is
     * on.
     */
    readonly costs: number | null;
    /**
     * What share of the page's parts that one place accounts for, or `null` on the
     * same terms as {@link PageUnread.costs}.
     */
    readonly share: number | null;
};

type DeploymentPlace = {
    readonly treeId: TreeId;
    readonly revision: number;
    readonly audienceId: AudienceId | null;
    /** The place itself, carried whole off its page's reading. */
    readonly at: UnreachedPart;
    /** What share of that page's parts this one place accounts for. */
    readonly share: number;
};

type DeploymentUnread = {
    /**
     * Every page with a place the reading stopped and a sound pair behind it,
     * worst first.
     */
    readonly ranked: readonly PageUnread[];
    /** Every other page, by tree id and newest revision first. */
    readonly unranked: readonly PageUnread[];
    /** The head of the order, which is the one place in this deployment to go to first. */
    readonly worst: PageUnread | null;
    /** How many pages stand in each state, over the ranked and the unranked alike. */
    readonly standings: Readonly<Record<UnreadStanding, number>>;
    /**
     * Distinct trees across every page read, which is not the number of pages.
     */
    readonly trees: number;
    /**
     * Places the reading stopped, added across the **ranked** pages.
     */
    readonly places: number;
    /**
     * Parts nobody reached, added across the **ranked** pages.
     */
    readonly unseen: number;
    /**
     * Pages whose reading names a part that said nothing while a part inside it
     * reported reach — a **slice** of the rows and not a further list.
     */
    readonly notReporting: readonly PageUnread[];
    /**
     * Readings of a revision beyond the first, which were dropped.
     */
