};

type ReaderWindowSources = {
    /** The counters, the funnel answers and the door rows. */
    readonly tallies: Pick<ReaderTallyStore, "tallies" | "funnels" | "pageViews">;
    /**
     * Where readers were, which is a second store and an optional one.
     */
    readonly regions?: Pick<ReaderRegionStore, "regions">;
};

type ReaderWindow = {
    readonly tallies: readonly StoredTally[];
    readonly funnels: readonly StoredFunnel[];
    readonly pageViews: readonly StoredPageViews[];
    /**
     * The region buckets, or `undefined` where no region store was offered.
     */
    readonly regions: readonly StoredRegionCount[] | undefined;
};

type WindowRevision = {
    readonly treeId: TreeId;
    readonly revision: number;
};

type RevisionTrees = {
    /** The tree at that revision, or `undefined` where this source has none. */
    readonly treeFor: (where: WindowRevision) => LoomTree | undefined;
};

type UnjoinedCause =
/**
 * The source has no tree at that revision.
 */
"no-tree"
/**
 * The source answered with a different page or a different revision from the
 * one asked for.
 */
 | "mismatched";

type UnjoinedRevision = WindowRevision & {
    readonly cause: UnjoinedCause;
    /** Counter rows left unread, so the cost of not drawing it is a number. */
    readonly tallies: number;
};

type WindowRegionReading = WindowRevision & {
    /**
     * The form these arrivals were served, or `null` where the rows named none.
     */
    readonly audienceId: AudienceId | null;
    /** The map itself, floored, as {@link regionReadingOf} reads it. */
    readonly reading: RegionReading;
};

type WindowRegionReadings = {
    /**
     * One map per revision, per form, in a stable order.
     */
    readonly maps: readonly WindowRegionReading[];
    /**
     * The deployment's readership, over every row in the window.
     */
    readonly readership: RegionReading;
    /**
     * Rows beyond the first for one tree, revision, form and region — dropped
     * from every map, and counted here.
     */
    readonly duplicated: number;
};

type DistinctRegionRows = {
    /** The first row for each tree, revision, form and region, in the order they arrived. */
    readonly kept: readonly StoredRegionCount[];
    /** Rows beyond the first for one of those keys, which are in {@link kept} nowhere. */
    readonly duplicated: number;
};

type WindowReadings = {
    /**
     * One reading per page, per revision, per form — which is what one reading is
     * — in a stable order.
     */
    readonly pages: readonly PageReading[];
    /** Revisions the rows name that have no reading, in the same order. */
    readonly unjoined: readonly UnjoinedRevision[];
    /**
     * Where the readers were, or `undefined` where no region store was offered.
     */
    readonly regions: WindowRegionReadings | undefined;
};

type WindowPair = PageForm & {
    /** The earlier side. Its revision is always below `now`'s. */
    readonly was: PageReading;
    readonly now: PageReading;
    /**
     * Revisions of this form the window holds below `was`, oldest first.
     */
    readonly superseded: readonly number[];
};

type UnpairedForm = PageForm & {
    /** The one reading of it, carried so a surface drawing the page still has it. */
    readonly reading: PageReading;
};

type WindowPairs = {
    /** One per form that has two revisions in the window, in a stable order. */
    readonly pairs: readonly WindowPair[];
    /** The forms that have one, in the same order. */
    readonly unpaired: readonly UnpairedForm[];
    /**
     * Readings handed in twice under one `readingKeyOf`, dropped before pairing.
     */
    readonly duplicated: number;
};

type FormPlacings = {
    /** Where that form belongs, or `undefined` where this source cannot say. */
    readonly placingFor: (form: PageForm) => FormPlacing | undefined;
};

type PlacedForm = PageForm & {
    readonly placing: FormPlacing;
};

type WindowLibraries = {
    /** The deployment's pages at the revisions the window opened on. */
    readonly was: LibraryWindow;
    /** The same pages at the revisions it closed on. */
    readonly now: LibraryWindow;
    /**
     * Forms held at one revision that the placings could not place, in a stable
     * order.
     */
    readonly unplaced: readonly UnpairedForm[];
    /**
     * Forms named more than once across `pairs` and `unpaired`, dropped after the
     * first.
     */
    readonly duplicated: number;
};

type DeploymentReadingContext = {
    /** The trees the window's revisions were filed against, as the caller holds them. */
    readonly trees: RevisionTrees;
    /** What each primitive declares it plays and says, from the registry. */
    readonly declarations: PartDeclarations;
    /**
     * The smallest region bucket this deployment will name, in page views.
     */
    readonly floor: number;
    /**
     * Where a form the window holds one revision of belongs.
     */
    readonly placings: FormPlacings;
};

type WindowAssembly = {
    /** One reading per page, per revision, per form, with the regions beside them. */
    readonly readings: WindowReadings;
    /** The before-and-afters, which is what five of the nine comparisons take. */
    readonly pairs: WindowPairs;
    /** The two libraries, which is what the other four take. */
    readonly libraries: WindowLibraries;
};

type WindowAgenda<TReason extends string = string> = {
    /**
     * Where reading stops on each page the window holds, in the readings' own
     * order.
     */
    readonly progress: readonly ReadingProgress[];
    /**
     * The pages by the readers each loses at its sharpest fall, worst first.
     */
    readonly order: DeploymentReading;
    /**
     * The pages by the readers each loses between the two ends of its sharpest
     * question, worst first.
     */
    readonly conversion: DeploymentConversion;
    /**
     * What is wrong with what this deployment collects, page by page.
     */
    readonly health: CollectionHealth;
    /**
     * Whether anything is arriving at this deployment, and what its door turned
     * away.
     */
    readonly arrival: ArrivalStanding<TReason>;
    /**
     * The pages by what one fix to each would recover, worst first, and every
     * place the reading of each stopped.
     */
    readonly unread: DeploymentUnread;
    /**
     * The fix-list: the two orders of pages, the measurements to repair, and the
     * one thing to do first.
     */
    readonly agenda: DeploymentAgenda;
};

type WindowFigures = {
    /**
     * Where the readers were and what the readers of each place read, or
     * `undefined` where no region store was offered.
     */
    readonly regions: RegionPagesReading | undefined;
    /** What the library asks of its readers' time, by kind of part, over every reading the window holds. */
    readonly pace: LibraryPace;
    /**
     * The states this window is in, over the caller's readings and the pace's own
     * rows.
     */
    readonly census: SilenceCensus;
    /**
     * Every entry the census was taken over, the caller's first and then the
     * pace's, so a caller may slice it and take a census of its own.
     */
    readonly silences: readonly ReadingSilence[];
};

type WindowFigureOptions = LibraryPaceOptions & {
    /**
     * The silences of the readings the caller took over this window's subjects,
     * one entry per reading and each already mapped through its own vocabulary's
     * `meaningOf…Silence`.
     */
    readonly silences?: readonly ReadingSilence[];
};

type FunnelPairing = {
    readonly was: FunnelReach;
    readonly now: FunnelReach;
};

type WindowFunnels = {
    /**
     * One answer per reading the window holds, in the readings' own order.
     */
    readonly pages: readonly FunnelReach[];
    /**
     * One before-and-after per form the window paired, in the pairs' own order.
     */
    readonly pairs: readonly FunnelPairing[];
};

type VisibilityObserver = {
    readonly observe: (element: Element) => void;
    readonly disconnect: () => void;
};

type VisibilityEntry = {
    readonly target: Element;
    readonly visible: boolean;
};

type ReaderSignalTypes = readonly string[] | {
    readonly [Kind in ReaderSignalKind]?: readonly string[];
};

type ReaderSignalOptions = {
    /** Called with every batch. A throw or rejection here is contained and never reaches the page. */
    readonly send?: (batch: ReaderSignalBatch) => void | Promise<void>;
    /** Which kinds to broadcast. Every kind when absent. */
    readonly kinds?: readonly ReaderSignalKind[];
    /**
     * Which primitive types to broadcast about. Every addressed type when absent.
     */
    readonly types?: ReaderSignalTypes;
    /** How often a batch is delivered. Five seconds when absent. */
    readonly flushEveryMs?: number;
    /**
     * How the broadcaster learns what is on screen. The browser's
     * `IntersectionObserver` when absent; a test passes its own.
     */
    readonly observeVisibility?: ObserveVisibility;
    /**
     * Whether a delegated signal carries the addressed nodes it happened inside.
     * On when absent.
     */
    readonly within?: boolean;
    /** The clock. `Date.now` when absent. */
    readonly now?: () => number;
    /**
     * Where the view key's randomness comes from. The browser's
     * `crypto.getRandomValues` when absent; a test passes its own so it can name
