    readonly since?: string | Date;
    readonly until?: string | Date;
}) => Result<TelemetryWindow, TelemetryWindowFault>

const telemetrySpanOf: (records: readonly {
    readonly recordedAt: string;
}[]) => TelemetrySpan | null

