type CollectingEventSink = EventSink & {
    readonly envelopes: readonly RuntimeEventEnvelope[];
    readonly types: () => readonly string[];
};

type RecordingModelClient = ModelClient & {
    readonly requests: readonly ModelRequest[];
};

type HangingModelClient = ModelClient & {
    /** Whether the runtime's ceiling aborted the call, and what it said. */
    readonly abortedWith: () => string | undefined;
};

type RecordingInterpreter = ChangeInterpreter & {
    readonly intents: readonly EditIntent[];
};

type RecordingRepairer = ChangeRepairer & {
    readonly requests: readonly RepairRequest[];
};

type IntentDraft = {
    readonly treeId: TreeId;
    readonly baseRevision: number;
    readonly utterance?: string;
    readonly origin?: IntentOrigin;
    readonly actor?: string;
};

type ProposalDraft = {
    readonly intentId: IntentId;
    readonly delta: TreeDelta;
    readonly rationale?: string;
    readonly origin?: IntentOrigin;
    readonly actor?: string;
    readonly authoredBy?: AuthorKind;
    readonly confidence?: number;
};

type HangingSeam<TEntry> = {
    readonly entry: TEntry;
    /** Whether the runtime's ceiling aborted the call, and what it said. */
    readonly abortedWith: () => string | undefined;
};

type AssessmentDraft = {
    /** The change being judged. Its delta decides what the inverse is written against. */
    readonly proposal: ProposedChange;
    /** What the delta does. The fields left out measure zero. */
    readonly analysis?: Partial<ChangeAnalysis>;
    /** The rules the Gate raised, in the order it raised them. */
    readonly factors?: readonly StakeFactor[];
    /** Why the change cannot be taken back. Empty means it can. */
    readonly irreversibilityReasons?: readonly IrreversibilityReason[];
    /**
     * Which of the write path's optional checks were in place. Empty by default,
     * which is what a double has wired: the real seams need a registry, and a
     * fixture claiming a check it never performed would put a reader's confidence
     * in the wrong place.
     */
    readonly wiredChecks?: readonly WriteCheck[];
};

type EpisodeHarness = {
    readonly path: WritePath;
    readonly journal: TelemetryJournal;
    readonly collector: TelemetryCollector;
    readonly tree: LoomTree;
    readonly ids: IdFactory;
    readonly intent: EditIntent;
    readonly fold: () => Promise<EpisodeFold>;
};

const harnessWith: (options: {
    readonly script: (tree: LoomTree, ids: IdFactory, intent: EditIntent) => Result<ProposedChange, InterpretationError>;
    readonly repairer?: (tree: LoomTree, ids: IdFactory, intent: EditIntent) => ChangeRepairer;
    readonly baseRevision?: number;
    /**
     * The Gate that judges this run. Defaults to the shipped one, which is what
     * most tests want; a test about attribution needs two hosts that differ, and
     * a policy is the only thing a disposition names.
     */
    readonly policy?: GatePolicy;
}) => Promise<EpisodeHarness>

